# -*- coding: utf-8 -*-
"""Тамагочи — питомец, который живёт в exteraGram.

Полноценная карманная игра про заботу, встроенная в мессенджер: питомец
вылупляется из яйца, растёт через четыре стадии, имеет собственные
характеристики по виду, требует ухода, гуляет по локациям, работает,
играет в мини-игры, носит аксессуары и красуется эмодзи-статусом у ника.

КАК УСТРОЕН ПЛАГИН
==================

Виды персонажей (SPECIES)
-------------------------
Десять видов: дракончик, котик, пингвинчик, призрак, пришелец, лисёнок,
крольчонок, робот, совёнок и медвежонок. У каждого свои:

* ``decay`` — индивидуальная скорость падения потребностей: дракончик
  прожорлив, призрак почти не грязнится, робот устаёт медленнее;
* ``likes`` / ``dislikes`` — любимая и нелюбимая еда: любимая кормит
  в полтора раза лучше, нелюбимая портит настроение и рискует
  несварением;
* ``unique`` — видовая активность: полетать, поохотиться, поплавать,
  напугать прохожих, изучить Землю, схитрить, попрыгать, подзарядиться,
  помудрствовать, помедитировать;
* ``walk_bonus`` — локация, где вид получает больше находок;
* характер, история, реплики для настроения, реакций на уход и болезни.

Стадии роста
------------
Яйцо → малыш → подросток → взрослый. Яйцо вылупляется, если его грели
и прошло время; подросток требует накопленной заботы; взрослым питомец
становится, когда заботы набрано достаточно и прошло трое суток.

Потребности
-----------
Сытость, настроение, чистота, бодрость, здоровье. Все падают со временем
(у каждого вида — со своей скоростью), во сне бодрость восстанавливается.
Ноль сытости или грязь долго — питомец заболевает; болезни лечатся
лекарствами из аптеки.

Экономика
---------
Монетки зарабатываются заботой, прогулками, работой, мини-играми,
ежедневным бонусом за серию посещений и достижениями. Тратятся в четырёх
магазинах: еда, игрушки, аксессуары, аптека. Из продуктов можно готовить
блюда по рецептам — сытнее и дешевле, чем покупать готовое.

* Каждое отправленное сообщение в любом чате чуть-чуть кормит питомца
  и приносит монетку (в пределах часа).
* Базовая каша бесплатна и всегда доступна, но слабая.

Прогулки
--------
Двенадцать локаций: от двора до вулкана и лунной станции. У каждой —
своя длительность, расход бодрости, пул событий и цена открытия. Во время
прогулки питомец находит монетки, еду, стикеры для альбома, попадает в
смешные ситуации, иногда пачкается или простывает. Погода меняет шансы.

Работа
------
Шесть профессий: курьер, охранник, художник, повар, астронавт,
испытатель. Отправляешь питомца на смену — по возвращении получает
зарплату, размер зависит от подходящего навыка и стадии.

Навыки
------
Ловкость, смекалка, сила и обаяние. Качаются мини-играми, тренировками,
прогулками и работой; уровни открывают лучшие исходы событий.

Мини-игры
---------
Напёрстки, реакция, память, викторина, кости и мышеловка — шесть игр
в диалогах, с наградами в монетках и опыте навыков.

Достижения
----------
Сорок с достижениями с наградами: от «первого обеда» до «полного альбома
стикеров». Прогресс считается по счётчикам, награда начисляется сама.

Гардероб
--------
Шляпы, шарфы, банты и прочее: три слота, пассивные бонусы (например,
цилиндр замедляет падение настроения). Носится с гордостью.

Альбом
------
Двадцать четыре коллекционных стикера, которые находятся на прогулках,
в играх и за достижения. Альбом показывает, чего не хватает.

Журнал
------
Хроника жизни питомца: вылупился, поел, вырос, заболел, вылечился,
нашёл стикер, сходил на работу. Последние события всегда под рукой.

Питомец у ника
--------------
Плагин ставит эмодзи-статус с текущей формой питомца — его видят все
рядом с именем, даже без плагина. Сам статус ставит Telegram, поэтому
нужен премиум; без него питомец просто живёт в плагине.

Приватность
-----------
Всё состояние — питомец, монеты, инвентарь, журнал — хранится локально
в настройках плагина и никуда не отправляется. Обращения к серверу
Telegram нужны только для эмодзи-статуса.
"""

