def _clamp(value, low=0.0, high=100.0):
    try:
        value = float(value)
    except (TypeError, ValueError):
        return low
    return max(low, min(high, value))


def _round(value):
    return int(round(_clamp(value)))


def _bar(value, width=8):
    """Полоска прогресса из блоков: ████····."""
    value = _clamp(value)
    filled = int(round(value / 100.0 * width))
    if value > 0 and filled < 1:
        filled = 1
    return "█" * filled + "·" * (width - filled)


def _plural(count, one, few, many):
    count = abs(int(count)) % 100
    if 11 <= count <= 14:
        return many
    count %= 10
    if count == 1:
        return one
    if 2 <= count <= 4:
        return few
    return many


def _coins_text(coins):
    return "%d %s" % (int(coins), _plural(coins, "монетка", "монетки", "монеток"))


def _duration_text(seconds):
    seconds = max(0, int(seconds))
    days, rest = divmod(seconds, 86400)
    hours, rest = divmod(rest, 3600)
    minutes = rest // 60
    if days:
        return "%d %s %d %s" % (days, _plural(days, "день", "дня", "дней"),
                                hours, _plural(hours, "час", "часа", "часов")) if hours else \
               "%d %s" % (days, _plural(days, "день", "дня", "дней"))
    if hours:
        return "%d %s" % (hours, _plural(hours, "час", "часа", "часов")) if not minutes else \
               "%d %s %d %s" % (hours, _plural(hours, "час", "часа", "часов"),
                                minutes, _plural(minutes, "минута", "минуты", "минут"))
    return "%d %s" % (max(1, minutes), _plural(minutes, "минута", "минуты", "минут"))


def _minutes_text(minutes):
    return _duration_text(max(0, int(minutes)) * 60)


def _clock_text(ts):
    try:
        stamp = time.localtime(ts)
        return "%02d.%02d.%04d %02d:%02d" % (
            stamp.tm_mday, stamp.tm_mon, stamp.tm_year, stamp.tm_hour, stamp.tm_min,
        )
    except Exception:
        return ""


def _today_key(ts=None):
    try:
        stamp = time.localtime(ts if ts is not None else time.time())
        return "%04d-%02d-%02d" % (stamp.tm_year, stamp.tm_mon, stamp.tm_mday)
    except Exception:
        return ""


def _daypart(ts=None):
    """Часть суток: утро, день, вечер, ночь."""
    try:
        hour = time.localtime(ts if ts is not None else time.time()).tm_hour
    except Exception:
        hour = 12
    if 5 <= hour < 12:
        return "morning"
    if 12 <= hour < 18:
        return "day"
    if 18 <= hour < 23:
        return "evening"
    return "night"


def _birthday_day(ts):
    """День рождения питомца: совпадение дня и месяца."""
    try:
        stamp = time.localtime(ts)
        return (stamp.tm_mon, stamp.tm_mday)
    except Exception:
        return (0, 0)


def _weighted(pairs):
    """Выборка из [(вес, значение), …]; сумма весов должна быть положительной."""
    total = sum(max(0.0, weight) for weight, _value in pairs)
    if total <= 0:
        return pairs[0][1] if pairs else None
    roll = random.random() * total
    for weight, value in pairs:
        roll -= max(0.0, weight)
        if roll <= 0:
            return value
    return pairs[-1][1]


def _to_list(value):
    """Java-список (ArrayList) или что угодно итерируемое — в список Python."""
    if value is None:
        return []
    try:
        return list(value)
    except BaseException:
        pass
    try:
        size = int(value.size())
    except BaseException:
        return []
    items = []
    for index in range(size):
        try:
            items.append(value.get(index))
        except BaseException:
            continue
    return items


def _face(state):
    needs = state.get("needs", {})
    if state.get("illness"):
        return "🤒"
    if needs.get("health", 100) <= 40:
        return "🤢"
    if state.get("sleep"):
        return "😴"
    average = sum(_clamp(needs.get(key, 100)) for key in NEED_KEYS) / float(len(NEED_KEYS))
    for threshold, face in FACE_TIERS:
        if average >= threshold:
            return face
    return "😢"


def _mood_word(state):
    needs = state.get("needs", {})
    average = sum(_clamp(needs.get(key, 100)) for key in NEED_KEYS) / float(len(NEED_KEYS))
    if average >= 75:
        return "счастлив"
    if average >= 50:
        return "доволен"
    if average >= 30:
        return "скучает"
    return "приуныл"


def _mood_bucket(state):
    """Корзина настроения для видовых реплик: great…bad."""
    needs = state.get("needs", {})
    average = sum(_clamp(needs.get(key, 100)) for key in NEED_KEYS) / float(len(NEED_KEYS))
    if average >= 75:
        return "great"
    if average >= 55:
        return "good"
    if average >= 40:
        return "okay"
    if average >= 25:
        return "low"
    return "bad"


