# ============================================================================
# ДВИЖОК: СОСТОЯНИЕ ПИТОМЦА
# ============================================================================
# Все функции работают с обычным словарём состояния и меткой времени;
# ничего не знают про Android — их можно тестировать хоть в консоли.
# Схема состояния:
#   species, stage, born, seen      — вид, стадия, рождение, последний тик
#   needs{...}                      — пять потребностей 0..100
#   sleep                           — спит ли
#   coins, care, care_score         — монеты, забота (эволюция), очки ранга
#   counters{...}                   — счётчики для достижений
#   inventory{item_id: {kind,count,uses}}
#   wardrobe{slot: acc_id}, outfits [надетое когда-либо]
#   skills{...}                     — опыт четырёх навыков
#   walk, job                       — активная прогулка / смена
#   illness                         — id болезни или None
#   journal [[ts, kind, text], ...] — хроника
#   daily                           — ежедевный бонус
#   collectibles, quests_done       — альбом и достижения
#   last{action: ts}                — перезарядки
#   chat                            — почасовой лимит «сообщенческого» корма
#   sync                            — когда и что ставили в статус
#   unlocked_locations              — открытые за монеты места прогулок

STATE_SCHEMA = 2


def species_of(state):
    return SPECIES.get(state.get("species")) or SPECIES["dragon"]


def new_state(species, now=None):
    now = time.time() if now is None else now
    return {
        "schema": STATE_SCHEMA,
        "species": species,
        "stage": 0,
        "born": now,
        "seen": now,
        "needs": {"satiety": 100.0, "mood": 100.0, "clean": 100.0,
                  "energy": 100.0, "health": 100.0},
        "sleep": False,
        "coins": START_COINS,
        "care": 0,
        "care_score": 0,
        "counters": {},
        "inventory": {},
        "wardrobe": {},
        "outfits": [],
        "skills": {"agility": 0, "wits": 0, "strength": 0, "charm": 0},
        "walk": None,
        "job": None,
        "illness": None,
        "journal": [],
        "daily": {"date": "", "streak": 0, "bonus": False},
        "collectibles": [],
        "quests_done": [],
        "last": {},
        "chat": {"window": 0, "count": 0},
        "sync": {"synced": 0, "stage": -1, "species": ""},
        "birthday": {"last_year": 0},
        "unlocked_locations": [],
        "foods_tried": [],
        "recipes_used": [],
        "jobs_tried": [],
        "weathers_seen": [],
    }


def migrate_state(state):
    """Дополняет старое состояние новыми полями, чтобы не потерять питомца."""
    fresh = new_state(state.get("species", "dragon"), state.get("born"))
    for key, value in fresh.items():
        state.setdefault(key, value)
    for key, value in fresh["needs"].items():
        state.setdefault("needs", {}).setdefault(key, value)
    for key, value in fresh["skills"].items():
        state.setdefault("skills", {}).setdefault(key, value)
    return state


def journal_add(state, kind, text, now=None):
    now = time.time() if now is None else now
    journal = state.setdefault("journal", [])
    journal.append([now, kind, text])
    if len(journal) > JOURNAL_MAX:
        del journal[: len(journal) - JOURNAL_MAX]


def counter_add(state, key, amount=1):
    counters = state.setdefault("counters", {})
    counters[key] = int(counters.get(key, 0)) + int(amount)
    return counters[key]


def counters_peak(state, key):
    """Текущее значение счётчика без изменения (для рекордов)."""
    return int((state.get("counters") or {}).get(key, 0))


def earn(state, coins, reason=""):
    coins = max(0, int(coins))
    if not coins:
        return 0
    state["coins"] = int(state.get("coins", 0)) + coins
    counter_add(state, "coins_earned", coins)
    if reason:
        pass  # причина нужна только вызывающему — для текста
    return coins


def spend(state, coins):
    coins = max(0, int(coins))
    if int(state.get("coins", 0)) < coins:
        return False
    state["coins"] = int(state.get("coins", 0)) - coins
    counter_add(state, "coins_spent", coins)
    return True


def skill_level(xp):
    xp = max(0, int(xp or 0))
    level = 0
    for threshold in SKILL_LEVEL_XP:
        if xp >= threshold:
            level += 1
        else:
            break
    return min(level, len(SKILL_LEVEL_XP) - 1)


def add_skill_xp(state, skill, xp):
    if skill not in SKILL_KEYS:
        return 0
    skills = state.setdefault("skills", {})
    before = skill_level(skills.get(skill, 0))
    skills[skill] = max(0, int(skills.get(skill, 0)) + int(xp))
    after = skill_level(skills[skill])
    if after > before:
        journal_add(state, "skill", "%s %s — уровень %d!" % (
            SKILL_ICONS[skill], SKILL_LABELS[skill], after))
        if after >= SKILL_MASTER_LEVEL and before < SKILL_MASTER_LEVEL:
            counter_add(state, "skills_lv5")
        if after >= 3 and before < 3:
            counter_add(state, "skills_at_3")
        if after >= SKILL_MASTER_LEVEL and before < SKILL_MASTER_LEVEL:
            counter_add(state, "skills_at_5")
    return after - before


def care_score_add(state, points=1):
    state["care_score"] = int(state.get("care_score", 0)) + int(points)
    counter_add(state, "care_points", points)
    return state["care_score"]


def rank_of(score):
    title = RANK_STEPS[0][1]
    for threshold, name in RANK_STEPS:
        if int(score) >= threshold:
            title = name
    return title


# ============================================================================
# ДВИЖОК: РАСПАД ПОТРЕБНОСТЕЙ
# ============================================================================

def decay_rates(state):
    """Итоговые скорости распада в час с учётом вида и гардероба."""
    species = species_of(state)
    multipliers = dict(species.get("decay", {}))
    for slot, acc_id in (state.get("wardrobe") or {}).items():
        accessory = ACCESSORIES.get(acc_id)
        if not accessory:
            continue
        for key, value in accessory.get("bonus", {}).items():
            if key in NEED_KEYS:
                multipliers[key] = multipliers.get(key, 1.0) * float(value)
    rates = {}
    for key, base in BASE_DECAY.items():
        rates[key] = base * multipliers.get(key, 1.0)
    return rates


def apply_decay(state, now=None):
    """Докручивает время, пока хозяин не заходил. Возвращает True, если что-то изменилось."""
    now = time.time() if now is None else now
    seen = float(state.get("seen", 0) or 0)
    if seen <= 0:
        state["seen"] = now
        return False
    hours = (now - seen) / 3600.0
    if hours < 1.0 / 60.0:  # меньше минуты — не считаем
        return False
    state["seen"] = now
    needs = state.setdefault("needs", {})
    if state.get("sleep"):
        for key, rate in SLEEP_RATES.items():
            needs[key] = _clamp(needs.get(key, 100) - rate * hours)
    else:
        rates = decay_rates(state)
        for key, rate in rates.items():
            needs[key] = _clamp(needs.get(key, 100) - rate * hours)

    # Здоровье: болезнь и голод грызут, покой лечит.
    if state.get("illness"):
        needs["health"] = _clamp(needs.get("health", 100) - HEALTH_DECAY_SICK * hours)
    elif needs.get("satiety", 100) <= 0.5:
        needs["health"] = _clamp(needs.get("health", 100) - HEALTH_DECAY_HUNGRY * hours)
    else:
        needs["health"] = _clamp(needs.get("health", 100) + HEALTH_REGEN * hours)

    if state.get("stage", 0) > 0:
        _maybe_catch_illness(state, hours, now)
    return True


def _maybe_catch_illness(state, hours, now=None):
    """Шанс подхватить болезнь за прошедшее время — от грязи и голода."""
    if state.get("illness"):
        return
    needs = state.get("needs", {})
    chance = SICK_CHANCE_PER_HOUR * hours
    if needs.get("clean", 100) <= SICK_CLEAN_THRESHOLD:
        chance += 0.25 * hours
    if needs.get("satiety", 100) <= 5:
        chance += 0.15 * hours
    if chance <= 0 or random.random() > min(0.9, chance):
        return
    if needs.get("clean", 100) <= SICK_CLEAN_THRESHOLD:
        illness = "dirt_rash"
    elif needs.get("satiety", 100) <= 5:
        illness = "indigestion"
    else:
        illness = random.choice(("cold", "blues"))
    catch_illness(state, illness, now)


def catch_illness(state, illness_id, now=None):
    if illness_id not in ILLNESSES:
        return
    state["illness"] = illness_id
    counter_add(state, "illnesses")
    journal_add(state, "ill", "Питомец приболел: %s %s" % (
        ILLNESSES[illness_id]["emoji"], ILLNESSES[illness_id]["name"]), now)


def cure_illness(state, now=None):
    illness = state.get("illness")
    if not illness:
        return None
    state["illness"] = None
    state.setdefault("needs", {})["health"] = _clamp(state["needs"].get("health", 100) + 25)
    counter_add(state, "healed")
    journal_add(state, "heal", "Питомец снова здоров и прыгает!", now)
    return illness


# ============================================================================
# ДВИЖОК: ЭВОЛЮЦИЯ
# ============================================================================

def check_evolution(state, now=None):
    """Проверяет переход на следующую стадию. Возвращает словарь флагов."""
    flags = {"hatched": False, "grown_teen": False, "grown_up": False, "changed": False}
    stage = int(state.get("stage", 0))
    if stage >= STAGE_COUNT - 1:
        return flags
    now = time.time() if now is None else now
    age = now - float(state.get("born", 0) or 0)
    care = int(state.get("care", 0))
    min_age, min_care = EVOLVE_STEPS[stage]
    if age < min_age or care < min_care:
        return flags
    state["stage"] = stage + 1
    flags["changed"] = True
    species = species_of(state)
    if stage == 0:
        flags["hatched"] = True
        for key in NEED_KEYS:
            state["needs"][key] = 90.0
        journal_add(state, "evolve", "Вылупился! Теперь это %s — %s." % (
            species["stages"][1], species["label"]))
    elif stage == 1:
        flags["grown_teen"] = True
        journal_add(state, "evolve", "%s подрос: теперь он %s." % (
            species["label"], species["stages"][2]))
    else:
        flags["grown_up"] = True
        counter_add(state, "adults_reached")
        journal_add(state, "evolve", "%s вырос — %s! Поздравляю." % (
            species["label"], species["stages"][3]))
    counter_add(state, "evolved")
    return flags


# ============================================================================
# ДВИЖОК: ИНВЕНТАРЬ
# ============================================================================

def inv_add(state, item_id, kind, count=1, uses=0):
    inventory = state.setdefault("inventory", {})
    entry = inventory.get(item_id)
    if entry is None:
        entry = {"kind": kind, "count": 0, "uses": int(uses)}
        inventory[item_id] = entry
    entry["kind"] = kind
    if kind == "toy":
        entry["uses"] = int(entry.get("uses", 0) or 0) + int(uses)
    else:
        entry["count"] = int(entry.get("count", 0) or 0) + int(count)
    return entry


def inv_take(state, item_id, count=1):
    """Забирает из инвентаря; возвращает True, если получилось."""
    inventory = state.setdefault("inventory", {})
    entry = inventory.get(item_id)
    if entry is None:
        return False
    if entry.get("kind") == "toy":
        return True  # игрушки не расходуются по count, только по uses
    if int(entry.get("count", 0) or 0) < count:
        return False
    entry["count"] = int(entry.get("count", 0)) - count
    if entry["count"] <= 0:
        del inventory[item_id]
    return True


def inv_count(state, item_id):
    entry = (state.get("inventory") or {}).get(item_id)
    if entry is None:
        return 0
    if entry.get("kind") == "toy":
        return int(entry.get("uses", 0) or 0)
    return int(entry.get("count", 0) or 0)


# ============================================================================
# ДВИЖОК: ЕДА И КОРМЛЕНИЕ
# ============================================================================

def food_info(food_id):
    return FOODS.get(food_id) or RECIPES.get(food_id)


def food_effect_for(state, food_id):
    """Эффект еды с учётом вкусов вида. Возвращает (effects, note, risk)."""
    food = food_info(food_id)
    if food is None:
        return {}, "", False
    species = species_of(state)
    effects = dict(food.get("effects", {}))
    note = ""
    risk = False
    if food_id in species.get("likes", ()):
        if "satiety" in effects:
            effects["satiety"] = int(round(effects["satiety"] * 1.5))
        effects["mood"] = effects.get("mood", 0) + 6
        note = "любимое блюдо — зашло на ура"
    elif food_id in species.get("dislikes", ()):
        if "satiety" in effects:
            effects["satiety"] = max(4, int(round(effects["satiety"] * 0.5)))
        effects["mood"] = effects.get("mood", 0) - 7
        risk = True
        note = "нелюбимая еда: съел через «фу», возможны последствия"
    return effects, note, risk


def eat_food(state, food_id, now=None):
    """Кормление. Возвращает (ok, строки-результат)."""
    now = time.time() if now is None else now
    if int(state.get("stage", 0)) == 0:
        return False, ["Яйцо не едят — его греют 🤲"]
    if state.get("sleep"):
        state["sleep"] = False
    food = food_info(food_id)
    if food is None:
        return False, ["Такого в кладовой нет"]
    free = food_id == BASIC_FOOD
    if not free and not inv_take(state, food_id):
        return False, ["Этого закончилось — купи или приготовь ещё"]
    effects, note, risk = food_effect_for(state, food_id)
    needs = state.setdefault("needs", {})
    lines = ["%s Съедено: %s" % (food["emoji"], food["name"])]
    for key, value in effects.items():
        if key in needs:
            needs[key] = _clamp(needs.get(key, 100) + value)
    if note:
        lines.append(note)
    eat_reactions = (SPECIES_EAT_LINES.get(state.get("species")) or {}).get(
        "likes" if food_id in species_of(state).get("likes", ()) else
        "dislikes" if food_id in species_of(state).get("dislikes", ()) else "normal", ())
    if eat_reactions:
        lines.append(random.choice(eat_reactions))
    counter_add(state, "fed")
    tried = state.setdefault("foods_tried", [])
    if food_id not in tried:
        tried.append(food_id)
        counter_add(state, "foods_tried")
    category = food.get("category", "basic")
    if category == "sweet":
        counter_add(state, "sweets_eaten")
    elif category == "healthy":
        counter_add(state, "healthy_eaten")
    state["care"] = int(state.get("care", 0)) + 1
    care_score_add(state)
    earn(state, EARN_CARE)
    journal_add(state, "feed", "Покормлен: %s %s" % (food["emoji"], food["name"]), now)
    if risk and random.random() < 0.35:
        catch_illness(state, "indigestion", now)
        lines.append("…и прихватило: похоже на несварение 🤢")
    return True, lines


def cook(state, recipe_id, now=None):
    """Готовка по рецепту. Возвращает (ok, строки-результат)."""
    now = time.time() if now is None else now
    recipe = RECIPES.get(recipe_id)
    if recipe is None:
        return False, ["Рецепт потерялся"]
    missing = [item for item in recipe["inputs"] if inv_count(state, item) < recipe["inputs"].count(item)]
    if missing:
        names = ", ".join(FOODS.get(item, {}).get("name", item) for item in missing)
        return False, ["Не хватает: %s" % names]
    for item in recipe["inputs"]:
        inv_take(state, item)
    inv_add(state, recipe_id, "food")
    counter_add(state, "cooked")
    if recipe_id not in (state.get("recipes_used") or []):
        state.setdefault("recipes_used", []).append(recipe_id)
        counter_add(state, "recipes_used")
    care_score_add(state)
    earn(state, EARN_CARE + 2)
    journal_add(state, "cook", "Приготовлено: %s %s" % (recipe["emoji"], recipe["name"]), now)
    return True, [
        "%s %s — готово!" % (recipe["emoji"], recipe["name"]),
        "Лежит в кладовой: накорми, пока тёплое",
    ]


# ============================================================================
# ДВИЖОК: МАГАЗИНЫ
# ============================================================================

SHOP_KINDS = {
    "food": {"title": "🥩 Еда", "items": FOODS, "inv_kind": "food"},
    "toy": {"title": "🧸 Игрушки", "items": TOYS, "inv_kind": "toy"},
    "accessory": {"title": "🎩 Аксессуары", "items": ACCESSORIES, "inv_kind": "accessory"},
    "medicine": {"title": "💊 Аптека", "items": MEDICINES, "inv_kind": "medicine"},
}


def buy(state, kind, item_id, now=None):
    """Покупка. Возвращает (ok, строки-результат)."""
    now = time.time() if now is None else now
    shop = SHOP_KINDS.get(kind)
    items = (shop or {}).get("items") or {}
    item = items.get(item_id)
    if item is None:
        return False, ["Такого не продают"]
    if item.get("unbuyable"):
        return False, ["Это не продаётся — только зарабатывается"]
    price = int(item.get("price", 0))
    if not spend(state, price):
        return False, ["Не хватает монет: нужно %s" % _coins_text(price)]
    if kind == "toy":
        inv_add(state, item_id, "toy", uses=int(item.get("uses", 1)))
    else:
        inv_add(state, item_id, kind)
    counter_add(state, "items_bought")
    counter_add(state, kind + "s_bought")
    journal_add(state, "buy", "Куплено: %s %s" % (item["emoji"], item["name"]), now)
    return True, ["%s %s — в сумке!" % (item["emoji"], item["name"])]


def unlock_location(state, loc_id, now=None):
    location = LOCATIONS.get(loc_id)
    if location is None:
        return False, ["Такого места нет на карте"]
    if loc_id in (state.get("unlocked_locations") or []):
        return True, ["Уже открыто"]
    price = int(location.get("price", 0))
    if not spend(state, price):
        return False, ["Нужно %s на открытие" % _coins_text(price)]
    state.setdefault("unlocked_locations", []).append(loc_id)
    counter_add(state, "locations_opened")
    journal_add(state, "unlock", "Открыто место прогулок: %s %s" % (
        location["emoji"], location["name"]))
    return True, ["%s открыто для прогулок!" % location["name"]]


# ============================================================================
# ДВИЖОК: ИГРУШКИ, ЛЕКАРСТВА, ГАРДЕРОБ
# ============================================================================

def play_with_toy(state, toy_id, now=None):
    """Игра с игрушкой из инвентаря. Возвращает (ok, строки)."""
    now = time.time() if now is None else now
    toy = TOYS.get(toy_id)
    entry = (state.get("inventory") or {}).get(toy_id)
    if toy is None or entry is None or int(entry.get("uses", 0) or 0) <= 0:
        return False, ["Такой игрушки больше нет — она своё отыграла"]
    if state.get("sleep"):
        state["sleep"] = False
    entry["uses"] = int(entry.get("uses", 0)) - 1
    lines = ["%s Играли в %s" % (toy["emoji"], toy["name"].lower())]
    needs = state.setdefault("needs", {})
    needs["mood"] = _clamp(needs.get("mood", 100) + int(toy.get("mood", 12)))
    needs["energy"] = _clamp(needs.get("energy", 100) - 5)
    add_skill_xp(state, "agility", 4)
    counter_add(state, "played")
    state["care"] = int(state.get("care", 0)) + 1
    care_score_add(state)
    earn(state, EARN_CARE)
    journal_add(state, "play", "Играли: %s %s" % (toy["emoji"], toy["name"]), now)
    toy_line = TOY_REACTION_LINES.get(toy_id)
    if toy_line:
        lines.append(random.choice(toy_line))
    if entry["uses"] <= 0:
        del state["inventory"][toy_id]
        lines.append("Игрушка отслужила своё и осталась в воспоминаниях")
    check_evolution(state, now)
    return True, lines


def use_medicine(state, med_id, now=None):
    now = time.time() if now is None else now
    medicine = MEDICINES.get(med_id)
    if medicine is None or not inv_take(state, med_id):
        return False, ["В аптечке пусто"]
    lines = ["%s %s — принято" % (medicine["emoji"], medicine["name"])]
    needs = state.setdefault("needs", {})
    for key, value in medicine.get("effects", {}).items():
        if key in needs:
            needs[key] = _clamp(needs.get(key, 100) + value)
    illness = state.get("illness")
    if illness and illness in medicine.get("cures", ()):
        cured = cure_illness(state, now)
        counter_add(state, "healed")
        lines.append("%s — питомец выздоровел!" % ILLNESSES[cured]["name"])
        lines.append(random.choice(HEALED_LINES))
    elif illness:
        lines.append("Стало легче, но болезнь пока с нами")
    journal_add(state, "heal", "Лекарство: %s" % medicine["name"], now)
    return True, lines


def equip_accessory(state, acc_id, now=None):
    now = time.time() if now is None else now
    accessory = ACCESSORIES.get(acc_id)
    entry = (state.get("inventory") or {}).get(acc_id)
    if accessory is None or entry is None:
        return False, ["Такого аксессуара нет в гардеробе"]
    wardrobe = state.setdefault("wardrobe", {})
    slot = accessory.get("slot", "head")
    previous = wardrobe.get(slot)
    wardrobe[slot] = acc_id
    if acc_id not in (state.get("outfits") or []):
        state.setdefault("outfits", []).append(acc_id)
        counter_add(state, "outfits_tried")
    if len(wardrobe) >= len(ACCESSORY_SLOTS):
        counter_add(state, "full_outfits")
    journal_add(state, "outfit", "Надето: %s %s" % (accessory["emoji"], accessory["name"]), now)
    lines = ["%s %s надет" % (accessory["emoji"], accessory["name"])]
    if previous and previous != acc_id:
        lines.append("%s отправлен в шкаф" % ACCESSORIES[previous]["name"])
    return True, lines


def unequip_slot(state, slot, now=None):
    wardrobe = state.setdefault("wardrobe", {})
    acc_id = wardrobe.get(slot)
    if not acc_id:
        return False, ["Там и так пусто"]
    del wardrobe[slot]
    journal_add(state, "outfit", "Снято: %s" % ACCESSORIES[acc_id]["name"])
    return True, ["%s снят" % ACCESSORIES[acc_id]["name"]]


def worn_emojis(state):
    wardrobe = state.get("wardrobe") or {}
    return [ACCESSORIES[acc_id]["emoji"] for acc_id in wardrobe.values() if acc_id in ACCESSORIES]


def walk_coin_scale(state):
    """Множитель монет с прогулок от гардероба."""
    scale = 1.0
    for slot, acc_id in (state.get("wardrobe") or {}).items():
        accessory = ACCESSORIES.get(acc_id)
        if accessory:
            scale *= float(accessory.get("bonus", {}).get("walk_coins", 1.0))
    return scale


# ============================================================================
# ДВИЖОК: ВИДОВАЯ АКТИВНОСТЬ И ПРОСТОЙ УХОД
# ============================================================================

def do_unique(state, now=None):
    """Фирменная активность вида. Возвращает (ok, строки)."""
    now = time.time() if now is None else now
    species = species_of(state)
    action_id = species.get("unique")
    action = UNIQUE_ACTIONS.get(action_id)
    if action is None:
        return False, ["У этого вида пока нет фирменного номера"]
    if int(state.get("stage", 0)) == 0:
        return False, ["Яйцо исполняет только трюк «лежать и греется»"]
    if state.get("sleep"):
        state["sleep"] = False
    last = float((state.get("last") or {}).get("unique_" + action_id, 0) or 0)
    cooldown = int(action.get("cooldown", 1800))
    if now - last < cooldown:
        left = int((cooldown - (now - last)) / 60) + 1
        return False, ["Не сейчас: лапки заняты, подожди ~%d мин" % left]
    state.setdefault("last", {})["unique_" + action_id] = now

    needs = state.setdefault("needs", {})
    lines = []
    for key, value in action.get("effects", {}).items():
        if key in needs:
            needs[key] = _clamp(needs.get(key, 100) + value)
    coin_min, coin_max = action.get("coins", (0, 0))
    coins = random.randint(coin_min, coin_max) if coin_max > 0 else 0
    if coins > 0:
        coins = int(round(coins * walk_coin_scale(state)))
        earn(state, coins)
        lines.append("Намыто %s" % _coins_text(coins))
    find_food = action.get("find_food")
    if find_food and random.random() < 0.3:
        found = random.choice(find_food)
        inv_add(state, found, "food")
        lines.append("Принёс в подарок: %s %s" % (
            FOODS[found]["emoji"], FOODS[found]["name"].lower()))
    skill_xp = action.get("skill_xp")
    if skill_xp:
        add_skill_xp(state, skill_xp[0], skill_xp[1])
    if action.get("skill"):
        add_skill_xp(state, action["skill"], 5)

    reaction = species.get("reactions", {}).get("unique")
    if reaction:
        lines.append(random.choice(reaction))
    unique_line = UNIQUE_RESULT_LINES.get(action_id)
    if unique_line:
        lines.append(random.choice(unique_line))
    counter_add(state, "unique_used")
    counter_add(state, "uniques_done")
    state["care"] = int(state.get("care", 0)) + 1
    care_score_add(state)
    earn(state, EARN_CARE)
    journal_add(state, "unique", action["label"].split(" ", 1)[-1], now)
    check_evolution(state, now)
    return True, lines


def do_care(state, action, now=None):
    """Простой уход: pet/feed-free/warm/play/wash/sleep/train.
    Возвращает (ok, строки). Кормление едой — отдельной eat_food,
    игра с игрушкой — play_with_toy."""
    now = time.time() if now is None else now
    stage = int(state.get("stage", 0))
    species = species_of(state)

    if action == "sleep":
        if stage == 0:
            return False, ["Яйцо спит всегда — это его работа"]
        sleeping = bool(state.get("sleep"))
        state["sleep"] = not sleeping
        if state["sleep"]:
            counter_add(state, "sleeps")
            care_score_add(state)
            journal_add(state, "sleep", "Уложен спать")
            return True, [random.choice(species["reactions"]["sleep"])]
        journal_add(state, "sleep", "Проснулся")
        return True, ["Питомец проснулся и готов к делам"]

    cooldown = CARE_COOLDOWN.get(action, 0)
    last = float((state.get("last") or {}).get(action, 0) or 0)
    if cooldown and now - last < cooldown:
        left = int((cooldown - (now - last)) / 60) + 1
        return False, ["Не так часто: подожди ~%d мин" % left]

    if action == "warm":
        if stage != 0:
            return False, ["Это уже не яйцо — ему нужно другое"]
        state.setdefault("last", {})[action] = now
        state["care"] = int(state.get("care", 0)) + 1
        care_score_add(state)
        counter_add(state, "warmed")
        earn(state, EARN_CARE)
        journal_add(state, "warm", "Яйцо погрето на ладонях", now)
        lines = ["🤲 Яйцо в тепле. " + random.choice(species["reactions"]["sleep"])]
        flags = check_evolution(state, now)
        if flags["hatched"]:
            lines.append("Скорлупа треснула — сейчас что-то будет!")
        return True, lines

    if stage == 0:
        return False, ["Из яйца пока только греются 🤲"]

    state.setdefault("last", {})[action] = now
    needs = state.setdefault("needs", {})
    if state.get("sleep"):
        state["sleep"] = False

    if action == "pet":
        needs["mood"] = _clamp(needs.get("mood", 100) + 8)
        counter_add(state, "petted")
        care_score_add(state)
        return True, ["🤗 " + random.choice(species["reactions"]["play"])]

    if action == "play":
        needs["mood"] = _clamp(needs.get("mood", 100) + 18)
        needs["energy"] = _clamp(needs.get("energy", 100) - 6)
        counter_add(state, "played")
        state["care"] = int(state.get("care", 0)) + 1
        care_score_add(state)
        earn(state, EARN_CARE)
        add_skill_xp(state, "agility", 3)
        journal_add(state, "play", "Поиграли без игрушек", now)
        return True, ["🎾 " + random.choice(species["reactions"]["play"])]

    if action == "wash":
        needs["clean"] = _clamp(needs.get("clean", 100) + 40)
        needs["mood"] = _clamp(needs.get("mood", 100) + 3)
        counter_add(state, "washed")
        state["care"] = int(state.get("care", 0)) + 1
        care_score_add(state)
        earn(state, EARN_CARE)
        journal_add(state, "wash", "Помыт с пеной и мочалкой", now)
        return True, ["🫧 " + random.choice(species["reactions"]["wash"])]

    if action == "train":
        skill = random.choice(SKILL_KEYS)
        needs["energy"] = _clamp(needs.get("energy", 100) - 8)
        needs["mood"] = _clamp(needs.get("mood", 100) + 4)
        levels = add_skill_xp(state, skill, 14)
        counter_add(state, "trained")
        care_score_add(state)
        earn(state, EARN_CARE)
        journal_add(state, "train", "Тренировка: %s" % SKILL_LABELS[skill], now)
        line = "%s Тренировка: %s +14 опыта" % (SKILL_ICONS[skill], SKILL_LABELS[skill])
        if levels:
            line += " — новый уровень %d!" % skill_level(state["skills"][skill])
        return True, [line]

    return False, ["Такого питомец пока не умеет"]


# ============================================================================
# ДВИЖОК: ПРОГУЛКИ
# ============================================================================
# Прогулка живёт в state["walk"]: локация, время старта, погода и заранее
# сгенерированная лента событий с привязкой к минутам. События применяются
# лениво — по мере прошедшего времени (walk_tick), поэтому питомец гуляет
# «сам», даже если приложение закрыто.

def roll_weather():
    return _weighted([(weight, name) for weight, name in WEATHER_WEIGHTS])


def _walk_event_pool(loc_id):
    location = LOCATIONS.get(loc_id) or LOCATIONS["yard"]
    return [(WALK_EVENTS[event_id].get("weight", 5), event_id)
            for event_id in location.get("events", ())
            if event_id in WALK_EVENTS]


def _roll_sticker(state):
    """Выбирает стикер по редкости; предпочитает ненайденные."""
    rarity = _weighted([(weight, name) for name, weight in RARITY_WEIGHTS.items()])
    pool = [key for key, item in COLLECTIBLES.items()
            if item["rarity"] == rarity and key not in (state.get("collectibles") or [])]
    if not pool:
        pool = [key for key in COLLECTIBLES
                if key not in (state.get("collectibles") or [])]
    if not pool:
        return None
    sticker = random.choice(pool)
    if COLLECTIBLES[sticker].get("rarity") == "legendary":
        counter_add(state, "legendary_stickers")
    return sticker


def start_walk(state, loc_id, now=None):
    """Отправляет питомца гулять. Возвращает (ok, строки)."""
    now = time.time() if now is None else now
    if state.get("walk"):
        return False, ["Питомец уже гуляет — дождись возвращения"]
    if state.get("job"):
        return False, ["Питомец на смене — гулять потом"]
    if int(state.get("stage", 0)) == 0:
        return False, ["Яйцо гуляет только в кармане"]
    location = LOCATIONS.get(loc_id)
    if location is None:
        return False, ["Такого места нет на карте"]
    if int(state.get("stage", 0)) < int(location.get("min_stage", 1)):
        return False, ["Сюда пускают только %s" % STAGE_LABELS_LOWER[location["min_stage"]]]
    if int(location.get("price", 0)) > 0 and loc_id not in (state.get("unlocked_locations") or []):
        ok, lines = unlock_location(state, loc_id, now)
        if not ok:
            return False, lines

    needs = state.setdefault("needs", {})
    if needs.get("energy", 100) < int(location.get("energy", 10)) + 5:
        return False, ["Питомец слишком устал — уложи его спать или дай подкрепиться"]
    if state.get("sleep"):
        state["sleep"] = False

    minutes = int(location.get("minutes", 20))
    weather_id = roll_weather()
    if weather_id not in (state.get("weathers_seen") or []):
        state.setdefault("weathers_seen", []).append(weather_id)
        counter_add(state, "weathers_seen")
    if weather_id in ("rain", "storm", "drizzle"):
        counter_add(state, "rain_walks")
    species = species_of(state)
    bonus_loc, bonus_scale = species.get("walk_bonus", ("", 1.0))
    timeline = []
    step = max(4, minutes // 6)
    for minute in range(step, minutes + 1, step):
        event_id = _weighted(_walk_event_pool(loc_id))
        timeline.append((minute, event_id))
    journal_add(state, "walk", "Ушёл гулять: %s %s. %s" % (
        location["emoji"], location["name"], random.choice(WALK_FAREWELL_LINES)), now)
    state["walk"] = {
        "loc": loc_id,
        "started": now,
        "minutes": minutes,
        "weather": weather_id,
        "timeline": timeline,
        "applied": 0,
        "log": [],
    }
    needs["energy"] = _clamp(needs.get("energy", 100) - int(location.get("energy", 10)))
    if loc_id == bonus_loc:
        state["walk"]["bonus"] = float(bonus_scale)
    journal_add(state, "walk", "Ушёл гулять: %s %s, %s" % (
        location["emoji"], location["name"], WEATHER[weather_id]["name"].lower()), now)
    return True, [
        "%s %s, %s %s" % (location["emoji"], location["name"],
                          WEATHER[weather_id]["emoji"], WEATHER[weather_id]["name"]),
        "Прогулка на %s — заходи проверить, как дела" % _minutes_text(minutes),
    ]


STAGE_LABELS_LOWER = ("яйцо", "малышей", "подростков", "взрослых")
STAGE_LABELS = ("Яйцо", "Малыш", "Подросток", "Взрослый")


def _apply_walk_event(state, event_id, now):
    """Применяет одно событие прогулки. Возвращает строку-результат."""
    event = WALK_EVENTS.get(event_id)
    walk = state["walk"] or {}
    weather = WEATHER.get(walk.get("weather", "sunny")) or WEATHER["sunny"]
    species = species_of(state)
    needs = state.setdefault("needs", {})
    lines = []
    pet_name = species["label"].lower()

    kind = event.get("kind")
    if kind == "coins":
        low = int(event.get("min", 3))
        high = int(event.get("max", 9))
        check = event.get("skill_check")
        if check:
            level = skill_level(state.get("skills", {}).get(check[0], 0))
            bonus_points = level * 2
            low += bonus_points
            high += bonus_points + check[1]
        coins = random.randint(low, high)
        coins = int(round(coins * float(weather.get("coins", 1.0)) * walk_coin_scale(state)))
        if walk.get("bonus"):
            coins = int(round(coins * walk["bonus"]))
        earn(state, coins)
        return "Нашёл %s" % _coins_text(coins)

    if kind == "food":
        pool = event.get("pool") or ("bread",)
        found = random.choice(pool)
        inv_add(state, found, "food")
        return "Принёс %s %s" % (FOODS[found]["emoji"], FOODS[found]["name"].lower())

    if kind == "sticker":
        sticker = _roll_sticker(state)
        if not sticker:
            earn(state, 8)
            return "Нашёл повторный стикер — обменял на 8 монет"
        state.setdefault("collectibles", []).append(sticker)
        counter_add(state, "stickers_found")
        return "Новый стикер в альбом: %s %s" % (
            COLLECTIBLES[sticker]["emoji"], COLLECTIBLES[sticker]["name"])

    for key in ("mood", "clean", "energy", "health"):
        if key in event:
            needs[key] = _clamp(needs.get(key, 100) + float(event[key]))
    if kind == "skill":
        add_skill_xp(state, event.get("skill", "agility"), int(event.get("xp", 5)))
    if event.get("cold_risk") and random.random() < 0.25:
        catch_illness(state, "cold", now)
        lines.append("…и слегка продулся 🤧")

    text = event.get("text", "что-то случилось")
    if "%s" in text:
        text = text % pet_name
    return text[0].upper() + text[1:] + (", " + " ".join(lines) if lines else ".")


def walk_tick(state, now=None):
    """Прокручивает прогулку: применяет все наступившие события.
    Возвращает (список новых строк, завершена ли прогулка)."""
    now = time.time() if now is None else now
    walk = state.get("walk")
    if not walk:
        return [], False
    elapsed_min = (now - float(walk.get("started", 0))) / 60.0
    fresh = []
    timeline = walk.get("timeline") or []
    index = int(walk.get("applied", 0))
    while index < len(timeline) and timeline[index][0] <= elapsed_min:
        minute, event_id = timeline[index]
        try:
            fresh.append(_apply_walk_event(state, event_id, now))
        except Exception:
            fresh.append("Что-то произошло, но питомец не рассказывает")
        index += 1
    walk["applied"] = index
    if fresh:
        walk.setdefault("log", []).extend(fresh)
    done = elapsed_min >= float(walk.get("minutes", 20))
    return fresh, done


def finish_walk(state, now=None, early=False):
    """Завершает прогулку и сводит итоги. Возвращает (ok, строки)."""
    now = time.time() if now is None else now
    fresh, _done = walk_tick(state, now)
    walk = state.get("walk")
    if not walk:
        return False, ["Питомец и не гулял"]
    location = LOCATIONS.get(walk.get("loc")) or LOCATIONS["yard"]
    weather = WEATHER.get(walk.get("weather", "sunny")) or WEATHER["sunny"]
    needs = state.setdefault("needs", {})
    elapsed = max(0, now - float(walk.get("started", 0)))

    lines = list(fresh)
    lines.insert(0, random.choice(WALK_RETURN_LINES))
    if elapsed < 60:
        lines.append("Сходил только до двери — настроение едва сдвинулось")
    else:
        needs["mood"] = _clamp(needs.get("mood", 100) + 6 + int(weather.get("mood", 0)))
        if "clean" in weather:
            needs["clean"] = _clamp(needs.get("clean", 100) + float(weather["clean"]))
        if weather.get("cold_risk") and random.random() < 0.15:
            catch_illness(state, "cold", now)
            lines.append("На обратном пути продуло: лёгкая простуда 🤧")
    counter_add(state, "walks")
    counter_add(state, "walk_minutes", int(elapsed // 60))
    if walk.get("loc") == "dino_valley":
        counter_add(state, "walked_dino_valley")
    if walk.get("weather") == "storm":
        counter_add(state, "storm_walks")
    walk_hour = time.localtime(now).tm_hour
    if walk_hour >= 22 or walk_hour < 5:
        counter_add(state, "night_walks")
    state["care"] = int(state.get("care", 0)) + 1
    care_score_add(state, 2)
    add_skill_xp(state, "strength", 4)
    journal_add(state, "walk", "Вернулся с прогулки: %s" % location["name"], now)
    state["walk"] = None
    check_evolution(state, now)
    return True, lines or ["Прогулка прошла тихо и приятно"]


# ============================================================================
# ДВИЖОК: РАБОТА
# ============================================================================

def start_job(state, job_id, now=None):
    now = time.time() if now is None else now
    if state.get("job"):
        return False, ["Питомец уже на смене"]
    if state.get("walk"):
        return False, ["Питомец гуляет — работа подождёт"]
    if int(state.get("stage", 0)) == 0:
        return False, ["Из яйца выйдет плохой работник — пока только греться"]
    job = JOBS.get(job_id)
    if job is None:
        return False, ["Такой вакансии нет"]
    if int(state.get("stage", 0)) < int(job.get("min_stage", 1)):
        return False, ["Берут только с опыта %s и выше" % STAGE_LABELS[job["min_stage"]]]
    needs = state.setdefault("needs", {})
    if needs.get("energy", 100) < int(job.get("energy", 10)) + 5:
        return False, ["Слишком устал для смены — сначала отдых"]
    if state.get("sleep"):
        state["sleep"] = False
    needs["energy"] = _clamp(needs.get("energy", 100) - int(job.get("energy", 10)))
    state["job"] = {"id": job_id, "started": now, "minutes": int(job.get("minutes", 30))}
    if job_id not in (state.get("jobs_tried") or []):
        state.setdefault("jobs_tried", []).append(job_id)
        counter_add(state, "jobs_tried")
    journal_add(state, "job", "Ушёл на смену: %s %s" % (job["emoji"], job["name"]), now)
    return True, [
        "%s %s — смена началась" % (job["emoji"], job["name"]),
        "Вернётся через %s" % _minutes_text(job.get("minutes", 30)),
    ]


def finish_job(state, now=None):
    now = time.time() if now is None else now
    job_state = state.get("job")
    if not job_state:
        return False, ["Питомец и не работал"]
    job = JOBS.get(job_state.get("id")) or JOBS["courier"]
    elapsed = max(0, now - float(job_state.get("started", 0)))
    if elapsed < float(job_state.get("minutes", 30)) * 60:
        left = int((float(job_state.get("minutes", 30)) * 60 - elapsed) / 60) + 1
        return False, ["Смена ещё не кончилась: ~%d мин" % left]

    low, high = job.get("pay", (10, 20))
    level = skill_level(state.get("skills", {}).get(job.get("skill", "strength"), 0))
    pay = random.randint(low, high) + level * 3 + int(state.get("stage", 1)) * 2
    earn(state, pay)
    add_skill_xp(state, job.get("skill", "strength"), 10)
    needs = state.setdefault("needs", {})
    needs["mood"] = _clamp(needs.get("mood", 100) + 5)
    counter_add(state, "jobs_done")
    if job_state.get("id") == "astronaut":
        counter_add(state, "astronaut_shifts")
    care_score_add(state, 2)
    if random.random() < 0.12:
        sticker = _roll_sticker(state)
        if sticker:
            state.setdefault("collectibles", []).append(sticker)
            counter_add(state, "stickers_found")
    journal_add(state, "job", "Смена окончена: %s. Зарплата — %s" % (
        job["name"], _coins_text(pay)), now)
    state["job"] = None
    check_evolution(state, now)
    return True, [
        "%s Смена окончена!" % job["emoji"],
        "Зарплата: %s (навык %s ур. %d)" % (_coins_text(pay), SKILL_LABELS[job["skill"]], level),
    ]


# ============================================================================
# ДВИЖОК: ЕЖЕДНЕВНОЕ И ДЕНЬ РОЖДЕНИЯ
# ============================================================================

def daily_check(state, now=None):
    """Бонус за визит. Возвращает словарь результата или None."""
    now = time.time() if now is None else now
    daily = state.setdefault("daily", {})
    today = _today_key(now)
    if daily.get("date") == today:
        return None
    yesterday = _today_key(now - 86400)
    streak = int(daily.get("streak", 0)) if daily.get("date") == yesterday else 0
    streak += 1
    streak = min(streak, DAILY_STREAK_CAP)
    coins = DAILY_BASE_COINS * streak
    daily["date"] = today
    daily["streak"] = streak
    daily["bonus"] = True
    if streak > int(counters_peak(state, "max_streak")):
        counter_add(state, "max_streak", streak - int(counters_peak(state, "max_streak")))
    earn(state, coins)
    counter_add(state, "days_visited")
    journal_add(state, "daily", "Бонус за визит: +%s (серия %d)" % (_coins_text(coins), streak), now)
    return {"coins": coins, "streak": streak}


def birthday_check(state, now=None):
    """Раз в год — праздник. Выдаёт торт и настроение."""
    now = time.time() if now is None else now
    born = float(state.get("born", 0) or 0)
    if born <= 0:
        return None
    mon_day = _birthday_day(now)
    born_mon_day = _birthday_day(born)
    year = time.localtime(now).tm_year
    records = state.setdefault("birthday", {})
    if mon_day != born_mon_day or int(records.get("last_year", 0)) >= year:
        return None
    if year <= time.localtime(born).tm_year:
        return None
    records["last_year"] = year
    inv_add(state, "birthday_cake", "food")
    earn(state, 60)
    needs = state.setdefault("needs", {})
    needs["mood"] = _clamp(needs.get("mood", 100) + 25)
    counter_add(state, "birthdays")
    age = year - time.localtime(born).tm_year
    journal_add(state, "party", "День рождения! Исполнилось %d %s" % (
        age, _plural(age, "год", "года", "лет")), now)
    return {"age": age}


# ============================================================================
# ДВИЖОК: ДОСТИЖЕНИЯ
# ============================================================================

def check_quests(state, now=None):
    """Начисляет награды за выполненные условия. Возвращает список текстов."""
    now = time.time() if now is None else now
    done = state.setdefault("quests_done", [])
    counters = state.setdefault("counters", {})
    texts = []
    for quest_id, quest in QUESTS.items():
        if quest_id in done:
            continue
        if int(counters.get(quest["counter"], 0)) < int(quest["target"]):
            continue
        done.append(quest_id)
        reward = quest.get("reward", {})
        parts = []
        if reward.get("coins"):
            earn(state, reward["coins"])
            parts.append(_coins_text(reward["coins"]))
        if reward.get("food"):
            inv_add(state, reward["food"], "food")
            parts.append(food_info(reward["food"])["name"].lower())
        if reward.get("toy"):
            inv_add(state, reward["toy"], "toy", uses=TOYS[reward["toy"]]["uses"])
            parts.append(TOYS[reward["toy"]]["name"].lower())
        if reward.get("accessory"):
            inv_add(state, reward["accessory"], "accessory")
            parts.append(ACCESSORIES[reward["accessory"]]["name"].lower())
        if reward.get("collectible"):
            if reward["collectible"] not in state.setdefault("collectibles", []):
                state["collectibles"].append(reward["collectible"])
                counter_add(state, "stickers_found")
            parts.append("стикер " + COLLECTIBLES[reward["collectible"]]["name"])
        journal_add(state, "quest", "Достижение «%s»: награда — %s" % (
            quest["title"], ", ".join(parts)), now)
        texts.append("🏆 %s — %s" % (quest["title"], ", ".join(parts) or "почёт и уважение"))
    return texts


# ============================================================================
# ДВИЖОК: КОРМ СООБЩЕНИЯМИ
# ============================================================================

def chat_feed(state, now=None):
    """Твоё отправленное сообщение: питомцу чуть теплее и плюс монетка."""
    now = time.time() if now is None else now
    if int(state.get("stage", 0)) == 0:
        return None
    chat = state.setdefault("chat", {})
    window = int(now // 3600)
    if int(chat.get("window", 0)) != window:
        chat["window"] = window
        chat["count"] = 0
    if int(chat.get("count", 0)) >= CHAT_CAP_PER_HOUR:
        return None
    chat["count"] = int(chat.get("count", 0)) + 1
    needs = state.setdefault("needs", {})
    needs["satiety"] = _clamp(needs.get("satiety", 100) + EARN_CHAT_MOOD)
    needs["mood"] = _clamp(needs.get("mood", 100) + EARN_CHAT_MOOD)
    earn(state, EARN_CHAT_COINS)
    counter_add(state, "messages_fed")
    if random.random() < 0.25:
        # иногда питомец комментирует «обед из сообщений» в журнале
        journal_add(state, "chat", random.choice(CHAT_FEED_LINES), now)
    return True


# ============================================================================
# КЛАСС ПЛАГИНА: ХРАНЕНИЕ, СОБЫТИЯ, СТАТУС У НИКА
# ============================================================================

class TamagochiCore:
    """Примесь: движок плагина без наследования BasePlugin.

    Загрузчик плагинов ищет в модуле subclass BasePlugin и берёт первый
    встреченный — поэтому вся иерархия здесь: примеси движка и диалогов,
    а BasePlugin наследует только финальный TamagochiPlugin в самом
    конце файла."""

    def on_plugin_load(self):
        self._pet = None
        self._ctx = None
        self._sync_busy = False
        try:
            self.logger.info("tamagochi catalog: " + _catalog_summary())
        except Exception:
            pass
        try:
            self._menu = self.add_menu_item(
                MenuItemData(
                    menu_type=MenuItemType.CHAT_ACTION_MENU,
                    text="Тамагочи: питомец",
                    item_id="tamagochi_open",
                    icon="msg_info",
                    priority=12,
                    on_click=self._on_menu,
                )
            )
        except BaseException:
            self.logger.exception("menu registration failed")
        try:
            self.add_on_send_message_hook()
        except BaseException:
            self.logger.exception("send message hook failed")
        try:
            state = self._state()
            if state is not None:
                run_on_queue(lambda: self._sync_if_needed(state), PLUGINS_QUEUE, 5000)
        except BaseException:
            self.logger.exception("load sync failed")

    def on_plugin_unload(self):
        pass

    # ---- события приложения ----

    def on_app_event(self, event_type):
        if event_type not in (AppEvent.START, AppEvent.RESUME):
            return
        try:
            state = self._state()
            if state is not None:
                self._sync_if_needed(state)
        except BaseException:
            self.logger.exception("app event failed")

    def on_send_message_hook(self, account, params):
        """Каждое отправленное сообщение — маленький обед для питомца."""
        try:
            state = self._load_state()
            if state is None:
                return None
            if chat_feed(state):
                self._save_state(state)
        except BaseException:
            self.logger.exception("chat feed failed")
        return None

    # ---- хранение ----

    def _load_state(self):
        try:
            raw = self.get_setting("pet", None)
        except Exception:
            raw = None
        if isinstance(raw, str):
            # на случай, если мост отдал JSON-строку, а не разобранный словарь
            try:
                raw = json.loads(raw)
            except Exception:
                raw = None
        if isinstance(raw, dict) and raw.get("species") in SPECIES:
            return migrate_state(raw)
        return None

    def _state(self, now=None):
        """Загрузить, прокрутить время, проверить эволюцию и сохранить."""
        now = time.time() if now is None else now
        state = self._load_state()
        if state is None:
            self._pet = None
            return None
        try:
            hour = time.localtime(now).tm_hour
            if 0 <= hour < 5:
                counter_add(state, "night_visits")
            elif hour < 7:
                counter_add(state, "morning_visits")
            changed = apply_decay(state, now)
            flags = check_evolution(state, now)
            walk_tick(state, now)
            if state.get("job"):
                if now - float(state["job"].get("started", 0)) >= float(state["job"].get("minutes", 30)) * 60:
                    try:
                        ok, lines = finish_job(state, now)
                        if ok:
                            run_on_ui_thread(lambda: self._result_dialog("Смена окончена", lines))
                    except BaseException:
                        self.logger.exception("job auto finish failed")
            quest_texts = check_quests(state, now)
            daily = daily_check(state, now)
            birthday = birthday_check(state, now)
            if changed or flags["changed"] or quest_texts or daily or birthday:
                self._save_state(state)
            if quest_texts:
                run_on_ui_thread(lambda: self._result_dialog("Достижения", quest_texts))
            if daily:
                text = "Бонус за визит: +%s. Серия дней: %d" % (
                    _coins_text(daily["coins"]), daily["streak"])
                run_on_ui_thread(lambda: BulletinHelper.show_success(text))
            if birthday:
                text = "🎂 Питомцу исполнилось %d! Торт уже в кладовой" % birthday["age"]
                party_line = (SPECIES_BIRTHDAY_LINES.get(state.get("species")) or ("Праздник удался!",))[0]
                run_on_ui_thread(lambda: self._result_dialog(
                    "День рождения", [text, party_line]))
            if flags["hatched"] or flags["grown_teen"] or flags["grown_up"]:
                self._sync_if_needed(state)
                run_on_ui_thread(lambda: self._evolve_dialog(flags))
        except BaseException:
            self.logger.exception("state tick failed")
        self._pet = state
        return state

    def _save_state(self, state):
        try:
            self.set_setting("pet", state)
        except Exception:
            self.logger.exception("pet save failed")

    # ---- эмодзи-статус у ника ----

    def _pet_name(self, state):
        try:
            name = str(self.get_setting("pet_name", "") or "").strip()
        except Exception:
            name = ""
        if name:
            return name
        return species_of(state)["label"]

    def _show_status_setting(self):
        try:
            return bool(self.get_setting("show_status", True))
        except Exception:
            return True

    def _sync_if_needed(self, state, force=False):
        if state is None:
            return
        if not self._show_status_setting():
            return
        now = time.time()
        sync = state.get("sync") or {}
        stage_changed = sync.get("stage") != state.get("stage") or sync.get("species") != state.get("species")
        overdue = now - float(sync.get("synced", 0) or 0) >= SYNC_EVERY
        if not force and not stage_changed and not overdue:
            return
        self._sync_status()

    def _sync_status(self):
        if self._sync_busy:
            return
        state = self._pet or self._load_state()
        if state is None or TLRPC is None:
            return
        species = species_of(state)
        stage = min(STAGE_COUNT - 1, max(0, int(state.get("stage", 0))))
        emoticon = species["emoji"][stage]
        self._sync_busy = True
        self._resolve_doc(emoticon, lambda doc: self._set_status(doc))

    def _resolve_doc(self, emoticon, done):
        """Ищет document_id кастомного эмодзи для статуса."""
        try:
            cached = self.get_setting("doc_" + emoticon, None)
            if cached:
                done(int(cached))
                return
        except Exception:
            pass
        try:
            if self.get_setting("docmiss_" + emoticon, False):
                done(None)
                return
        except Exception:
            pass
        try:
            request = TLRPC.TL_messages_searchCustomEmoji()
            request.emoticon = emoticon
            request.hash = 0
            account = self._account()
            callback = lambda response, error: run_on_queue(
                lambda: self._on_emoji_list(emoticon, response, error, done)
            )
            try:
                send_request(request, callback, account=account)
            except TypeError:
                send_request(request, callback)
        except BaseException:
            self.logger.exception("emoji search failed: %s" % traceback.format_exc())
            self._sync_busy = False
            done(None)

    def _on_emoji_list(self, emoticon, response, error, done):
        doc = 0
        if error is None and response is not None:
            for value in _to_list(getattr(response, "document_id", None)):
                try:
                    candidate = int(value)
                except Exception:
                    continue
                if candidate > 0:
                    doc = candidate
                    break
        if doc > 0:
            try:
                self.set_setting("doc_" + emoticon, doc)
            except Exception:
                pass
        else:
            try:
                self.set_setting("docmiss_" + emoticon, True)
            except Exception:
                pass
        done(doc if doc > 0 else None)

    def _set_status(self, doc):
        self._sync_busy = False
        if not doc or TL_account is None or TLRPC is None:
            return
        try:
            request = TL_account.updateEmojiStatus()
            status = TLRPC.TL_emojiStatus()
            status.document_id = int(doc)
            request.emoji_status = status
            account = self._account()
            callback = lambda response, error: run_on_queue(
                lambda: self._on_status_set(response, error)
            )
            try:
                send_request(request, callback, account=account)
            except TypeError:
                send_request(request, callback)
        except BaseException:
            self.logger.exception("status request failed")

    def _on_status_set(self, response, error):
        state = self._pet or self._load_state()
        if state is None:
            return
        state.setdefault("sync", {}).update({
            "synced": time.time(),
            "stage": int(state.get("stage", 0)),
            "species": state.get("species"),
        })
        self._save_state(state)
        if error is not None:
            text = str(getattr(error, "text", "") or error)
            self.logger.error("status set failed: %s", text)
            if "PREMIUM" in text.upper():
                self._tell_premium()
            return
        try:
            first = not bool(self.get_setting("status_ok", False))
            self.set_setting("status_ok", True)
            if first:
                run_on_ui_thread(
                    lambda: BulletinHelper.show_success("Питомец теперь красуется у твоего ника 🎉"))
        except Exception:
            pass

    def _tell_premium(self):
        try:
            if self.get_setting("told_premium", False):
                return
            self.set_setting("told_premium", True)
        except Exception:
            pass
        run_on_ui_thread(lambda: self._premium_dialog())

    def _premium_dialog(self):
        try:
            dialog = AlertDialogBuilder(self._activity())
            dialog.set_title("Питомца у ника")
            dialog.set_message(
                "Эмодзи-статус ставится только с Telegram Premium — так решило Telegram.\n\n"
                "Без премиума питомец всё равно живёт: растёт, ест, гуляет и ждёт тебя в плагине."
            )
            dialog.set_positive_button("Понятно", lambda builder, which: builder.dismiss())
            dialog.show()
        except Exception:
            self.logger.exception("premium dialog failed")

    def _account(self):
        try:
            return int(UserConfig.selectedAccount)
        except Exception:
            return 0

    # ========================================================================
    # ИНТЕРФЕЙС: КОНТЕКСТ ОКНА (урок Chat Stats 1.2.2)
    # ========================================================================

    def _activate(self, view):
        """Запоминает окно, в котором нажали строку настроек.

        Экран настроек плагина — отдельное окно, а get_last_fragment()
        видит экран позади него. dispatch_setting_click передаёт вьюху
        нажатой строки: её getContext() и есть нужное окно.
        """
        self._ctx = None
        if view is None:
            return
        try:
            context = view.getContext()
        except Exception:
            return
        if context is not None:
            self._ctx = context

    def _activity(self):
        context = getattr(self, "_ctx", None)
        if context is not None:
            try:
                if not bool(context.isFinishing()):
                    return context
            except Exception:
                return context
            self._ctx = None
        try:
            fragment = get_last_fragment()
            if fragment is None:
                return None
            return fragment.getParentActivity()
        except Exception:
            return None

    def _show_error_dialog(self, message):
        try:
            dialog = AlertDialogBuilder(self._activity())
            dialog.set_title("Тамагочи")
            dialog.set_message(str(message))
            dialog.set_positive_button("Понятно", lambda builder, which: builder.dismiss())
            dialog.show()
        except Exception:
            self.logger.exception("error dialog failed")
            BulletinHelper.show_error(str(message))

    def _result_dialog(self, title, lines):
        """Диалог со списком строк-результатов и возвратом к питомцу."""
        try:
            dialog = AlertDialogBuilder(self._activity())
            dialog.set_title(title)
            dialog.set_message("\n".join(str(line) for line in lines))
            dialog.set_positive_button("К питомцу", lambda builder, which: self._show_pet_dialog())
            dialog.set_negative_button("Закрыть", lambda builder, which: builder.dismiss())
            dialog.show()
        except Exception:
            self.logger.exception("result dialog failed")

    def _evolve_dialog(self, flags):
        state = self._pet or self._load_state()
        if state is None:
            return
        species = species_of(state)
        evolve_lines = SPECIES_EVOLVE_LINES.get(state.get("species")) or ()
        if flags.get("hatched"):
            title = "Вылупился!"
            message = "Встречай: %s! Погрей его вниманием — и он вырастет." % species["label"]
        elif flags.get("grown_up"):
            title = "Повзрослел!"
            message = "%s вырос — %s! Поздравляю." % (species["label"], species["stages"][3])
        else:
            title = "Подрос!"
            message = "%s теперь %s. Дальше — больше." % (species["label"], species["stages"][2])
        if evolve_lines:
            step = 2 if flags.get("grown_up") else 1 if flags.get("grown_teen") else 0
            message += "\n" + evolve_lines[step]
        try:
            dialog = AlertDialogBuilder(self._activity())
            dialog.set_title(title)
            view = self._pet_image(state, 170)
            if view is not None:
                note = self._text_view(message)
                container = self._vertical(view, note)
                if container is not None:
                    dialog.set_view(container, self._dialog_height())
                else:
                    dialog.set_message(message)
            else:
                dialog.set_message(message)
            dialog.set_positive_button("Ура", lambda builder, which: self._show_pet_dialog())
            dialog.set_negative_button("Позже", lambda builder, which: builder.dismiss())
            dialog.show()
        except Exception:
            self.logger.exception("evolve dialog failed")
            self._show_pet_dialog()

    # ========================================================================
    # ИНТЕРФЕЙС: ВЬЮХИ
    # ========================================================================

    def _dialog_height(self):
        try:
            return int(AndroidUtilities.displaySize.y * 0.55)
        except Exception:
            return -2

    def _color(self, key, fallback):
        try:
            from org.telegram.ui.ActionBar import Theme

            value = Theme.getColor(getattr(Theme, key))
            if value is not None:
                return value
        except Exception:
            pass
        return fallback

    def _text_view(self, text, size=13, bold=False, mono=False, color_key="key_dialogTextBlack", fallback=(40, 40, 46)):
        try:
            from android.graphics import Typeface
            from android.widget import TextView

            activity = self._activity()
            if activity is None:
                return None
            view = TextView(activity)
            view.setText(str(text))
            view.setTextSize(size)
            view.setTextColor(self._color(color_key, fallback))
            if bold:
                view.setTypeface(Typeface.DEFAULT_BOLD)
            elif mono:
                view.setTypeface(Typeface.MONOSPACE)
            view.setPadding(0, AndroidUtilities.dp(4), 0, AndroidUtilities.dp(4))
            return view
        except Exception:
            self.logger.exception("text view failed")
            return None

    def _vertical(self, *views):
        try:
            from android.widget import LinearLayout

            activity = self._activity()
            if activity is None:
                return None
            row = LinearLayout(activity)
            row.setOrientation(LinearLayout.VERTICAL)
            row.setPadding(AndroidUtilities.dp(18), AndroidUtilities.dp(6), AndroidUtilities.dp(18), AndroidUtilities.dp(4))
            for view in views:
                if view is not None:
                    row.addView(view, LinearLayout.LayoutParams(-1, -2))
            return row
        except Exception:
            self.logger.exception("vertical layout failed")
            return None

    def _pet_image(self, state, height_dp=170):
        """Анимированная карточка питомца (гифка по виду и стадии)."""
        try:
            from android.graphics import BitmapFactory
            from android.graphics.drawable import BitmapDrawable
            from android.widget import ImageView, LinearLayout

            activity = self._activity()
            if activity is None:
                return None
            stage = min(STAGE_COUNT - 1, max(0, int(state.get("stage", 0))))
            key = "%s_%d" % (state.get("species", "dragon"), stage)
            payload = PET_GIFS.get(key)
            if not payload:
                return None
            data = base64.b64decode(payload)
            drawable = None
            try:
                from android.graphics import ImageDecoder
                from java.nio import ByteBuffer

                source = ImageDecoder.createSource(ByteBuffer.wrap(data))
                drawable = ImageDecoder.decodeDrawable(source)
                try:
                    drawable.start()
                except Exception:
                    pass
            except Exception:
                bitmap = BitmapFactory.decodeByteArray(data, 0, len(data))
                if bitmap is not None:
                    drawable = BitmapDrawable(activity.getResources(), bitmap)
            if drawable is None:
                return None

            image = ImageView(activity)
            image.setImageDrawable(drawable)
            image.setScaleType(ImageView.ScaleType.FIT_CENTER)
            holder = LinearLayout(activity)
            holder.setOrientation(LinearLayout.VERTICAL)
            holder.setPadding(AndroidUtilities.dp(8), AndroidUtilities.dp(6), AndroidUtilities.dp(8), 0)
            holder.addView(image, LinearLayout.LayoutParams(-1, AndroidUtilities.dp(height_dp)))
            return holder
        except Exception:
            self.logger.exception("pet image failed")
            return None

    def _pet_card(self, state):
        """Карточка для диалога и экрана настроек: гифка + сводка."""
        if state is None:
            return None
        species = species_of(state)
        stage = int(state.get("stage", 0))
        needs = state.get("needs", {})
        if state.get("sleep"):
            greeting = random.choice(DREAM_LINES)
        elif state.get("illness"):
            greeting = random.choice(species.get("sick_lines") or ("Питомцу нездоровится…",))
        else:
            mood_pool = (SPECIES_MOOD_LINES.get(state.get("species")) or {}).get(_mood_bucket(state))
            if mood_pool and random.random() < 0.7:
                greeting = random.choice(mood_pool)
            else:
                greeting = random.choice(
                    species.get("idle") or DAY_GREETINGS.get(_daypart(), DAY_GREETINGS["day"]))

        header = "%s  %s — %s" % (_face(state), self._pet_name(state), species["stages"][stage])
        subline = "%s · %s · ранг: %s" % (
            species["trait"], _plural_age_line(state), rank_of(state.get("care_score", 0)))

        lines = []
        if state.get("illness"):
            illness = ILLNESSES.get(state["illness"]) or {}
            lines.append("%s %s: %s" % (illness.get("emoji", "🤒"), illness.get("name", "Болезнь"),
                                        illness.get("symptom", "")))
            flavor = ILLNESS_FLAVOR.get(state["illness"])
            if flavor:
                lines.append(random.choice(flavor))
        if state.get("sleep"):
            lines.append("😴 Спит — бодрость восстанавливается")
        if state.get("walk"):
            walk = state["walk"]
            location = LOCATIONS.get(walk.get("loc")) or {}
            weather = WEATHER.get(walk.get("weather", "sunny")) or {}
            left = max(0, int(walk.get("minutes", 20) - (time.time() - walk.get("started", 0)) / 60))
            lines.append("%s Гуляет: %s %s · осталось ~%s" % (
                location.get("emoji", "🌳"), location.get("name", ""),
                weather.get("emoji", ""), _minutes_text(left)))
        if state.get("job"):
            job = JOBS.get(state["job"].get("id")) or {}
            left = max(0, int(float(state["job"].get("minutes", 30)) -
                              (time.time() - state["job"].get("started", 0)) / 60))
            lines.append("%s На смене: %s · осталось ~%s" % (
                job.get("emoji", "💼"), job.get("name", ""), _minutes_text(left)))

        stat_lines = []
        weak = [key for key in NEED_KEYS if _clamp(needs.get(key, 100)) < NEED_HINT_AT]
        if weak and not state.get("sleep"):
            stat_lines.append("💡 " + random.choice(NEED_HINTS[random.choice(weak)]))
        if stage == 0:
            stat_lines.append("🥚 %s" % species["stage_notes"][0])
        else:
            for key in NEED_KEYS:
                stat_lines.append("%s %s %3d" % (
                    NEED_ICONS[key], _bar(needs.get(key, 100)), _round(needs.get(key, 100))))

        views = []
        image = self._pet_image(state, 160)
        if image is not None:
            views.append(image)
        views.append(self._text_view(header, size=15, bold=True))
        views.append(self._text_view(subline, size=12, color_key="key_dialogTextGray", fallback=(120, 120, 128)))
        views.append(self._text_view(greeting, size=12, color_key="key_dialogTextGray", fallback=(120, 120, 128)))
        for line in lines:
            views.append(self._text_view(line, size=12, bold=True,
                                         color_key="key_windowBackgroundWhiteOrange", fallback=(200, 120, 40)))
        for line in stat_lines:
            views.append(self._text_view(line, size=13, mono=True))
        worn = worn_emojis(state)
        if worn:
            views.append(self._text_view("Носит: " + " ".join(worn), size=12,
                                         color_key="key_dialogTextGray", fallback=(120, 120, 128)))
        views.append(self._text_view("💰 %s · 🏆 %d/%d достижений · 🧩 %d/%d стикеров" % (
            _coins_text(state.get("coins", 0)),
            len(state.get("quests_done") or []), len(QUESTS),
            len(state.get("collectibles") or []), len(COLLECTIBLES)),
            size=12, color_key="key_dialogTextGray", fallback=(120, 120, 128)))
        return self._vertical(*[view for view in views if view is not None])


def _plural_age_line(state):
    born = float(state.get("born", 0) or 0)
    if born <= 0:
        return "возраст неизвестен"
    seconds = time.time() - born
    days = int(seconds // 86400)
    hours = int(seconds // 3600)
    if days >= 1:
        return "с нами %d %s" % (days, _plural(days, "день", "дня", "дней"))
    if hours >= 1:
        return "с нами %d %s" % (hours, _plural(hours, "час", "часа", "часов"))
    return "в этом мире всего ничего"


# ============================================================================
# ИНТЕРФЕЙС: ГЛАВНЫЙ ДИАЛОГ ПИТОМЦА
# ============================================================================
# Методы класса продолжаются во второй секции файла — так проще ориентироваться.

class TamagochiDialogs(TamagochiCore):
    """Примесь диалогов: забота, еда, магазины, кухня. Наследует движок."""

    # ---- главный диалог ----

    def _show_pet_dialog(self, message=None):
        try:
            state = self._state()
            if state is None:
                self._pick_species()
                return
            dialog = AlertDialogBuilder(self._activity())
            dialog.set_title("Тамагочи")
            card = self._pet_card(state)
            if card is not None:
                if message:
                    note = self._text_view(message, size=13, bold=True,
                                           color_key="key_windowBackgroundWhiteBlueText",
                                           fallback=(46, 110, 220))
                    card = self._vertical(card, note) or card
                dialog.set_view(card, self._dialog_height())
            else:
                dialog.set_message(message or "Питомец ждёт заботы")

            items, actions = [], []
            stage = int(state.get("stage", 0))
            if stage == 0:
                items.append(CARE_TITLES["warm"])
                actions.append(("care", "warm"))
            else:
                items.extend([CARE_TITLES["feed"], CARE_TITLES["play"], CARE_TITLES["wash"]])
                actions.extend([("care", "feed"), ("care", "play"), ("care", "wash")])
                items.append("⏰ Разбудить" if state.get("sleep") else "😴 Уложить спать")
                actions.append(("care", "sleep"))
                species = species_of(state)
                unique = UNIQUE_ACTIONS.get(species.get("unique"))
                if unique:
                    items.append(unique["label"])
                    actions.append(("unique", species["unique"]))
                items.append("🚶 Гулять")
                actions.append(("walk", None))
                if state.get("job"):
                    items.append("💼 Забрать со смены")
                    actions.append(("job_finish", None))
                else:
                    items.append("💼 На работу")
                    actions.append(("job_list", None))
            items.extend(["🎮 Мини-игры", "🛒 Магазин", "🎒 Кладовая", "🏆 Ещё"])
            actions.extend([("games", None), ("shop", None), ("inventory", None), ("more", None)])

            def pick(builder, index):
                try:
                    builder.dismiss()
                except Exception:
                    pass
                if 0 <= index < len(actions):
                    self._run_hub_action(actions[index][0], actions[index][1])

            dialog.set_items(items, pick)
            dialog.set_negative_button("Закрыть", lambda builder, which: builder.dismiss())
            dialog.show()
        except BaseException:
            self.logger.exception("pet dialog failed")
            self._show_error_dialog("Не получилось открыть питомца")

    def _run_hub_action(self, kind, payload):
        table = {
            "care": lambda: self._care_and_show(payload),
            "unique": lambda: self._unique_and_show(),
            "walk": self._pick_location,
            "job_list": self._pick_job,
            "job_finish": self._finish_job_and_show,
            "games": self._pick_game,
            "shop": self._pick_shop,
            "inventory": self._show_inventory,
            "more": self._show_more,
        }
        handler = table.get(kind)
        if handler:
            try:
                handler()
            except BaseException:
                self.logger.exception("hub action failed: %s" % kind)
                self._show_error_dialog("Что-то сломалось — глянь лог")

    # ---- уход ----

    def _care_and_show(self, action):
        state = self._pet or self._state()
        if state is None:
            self._pick_species()
            return
        if action == "feed":
            self._pick_food()
            return
        ok, lines = do_care(state, action)
        if action == "play":
            # если есть игрушка — играем с ней, эффектнее
            toys = [key for key, entry in (state.get("inventory") or {}).items()
                    if entry.get("kind") == "toy" and int(entry.get("uses", 0) or 0) > 0]
            if toys:
                ok, lines = play_with_toy(state, random.choice(toys))
        self._save_state(state)
        self._after_action(ok, lines)

    def _unique_and_show(self):
        state = self._pet or self._state()
        if state is None:
            return
        ok, lines = do_unique(state)
        self._save_state(state)
        self._after_action(ok, lines)

    def _after_action(self, ok, lines):
        if ok:
            BulletinHelper.show_success(lines[0] if lines else "Готово")
        else:
            BulletinHelper.show_error(lines[0] if lines else "Не сейчас")
        state = self._state()
        if state is not None:
            self._sync_if_needed(state)
        self._show_pet_dialog(message="\n".join(lines))

    def _pick_food(self):
        """Выбор еды: кладовая + бесплатная каша + покупка на ходу."""
        state = self._pet or self._state()
        if state is None:
            return
        species = species_of(state)
        items = ["🥣 %s (бесплатно)" % FOODS[BASIC_FOOD]["name"]]
        ids = [BASIC_FOOD]
        for food_id, entry in sorted((state.get("inventory") or {}).items()):
            if entry.get("kind") != "food":
                continue
            food = food_info(food_id)
            if not food:
                continue
            mark = ""
            if food_id in species.get("likes", ()):
                mark = " ❤️"
            elif food_id in species.get("dislikes", ()):
                mark = " 💢"
            items.append("%s %s ×%d%s" % (food["emoji"], food["name"],
                                          int(entry.get("count", 0)), mark))
            ids.append(food_id)
        items.append("🛒 Купить еду")
        ids.append("__shop__")

        def pick(builder, index):
            try:
                builder.dismiss()
            except Exception:
                pass
            if not 0 <= index < len(ids):
                return
            if ids[index] == "__shop__":
                self._pick_shop("food")
                return
            ok, lines = eat_food(state, ids[index])
            self._save_state(state)
            self._after_action(ok, lines)

        try:
            dialog = AlertDialogBuilder(self._activity())
            dialog.set_title("Чем покормить?")
            dialog.set_message("❤️ — любимое, 💢 — нелюбимое")
            dialog.set_items(items, pick)
            dialog.set_negative_button("Отмена", lambda builder, which: builder.dismiss())
            dialog.show()
        except Exception:
            self.logger.exception("food dialog failed")

    # ---- магазин ----

    def _pick_shop(self, kind=None):
        state = self._pet or self._state()
        if state is None:
            return
        if kind:
            self._shop_list(kind)
            return
        items = ["%s — %s" % (shop["title"], SHOP_CATEGORY_NOTES.get(kind, ""))
                 for kind, shop in SHOP_KINDS.items()]
        kinds = list(SHOP_KINDS.keys())

        def pick(builder, index):
            try:
                builder.dismiss()
            except Exception:
                pass
            if 0 <= index < len(kinds):
                self._shop_list(kinds[index])

        try:
            dialog = AlertDialogBuilder(self._activity())
            dialog.set_title("Магазин")
            dialog.set_message("В кошельке: %s" % _coins_text(state.get("coins", 0)))
            dialog.set_items(items, pick)
            dialog.set_negative_button("Закрыть", lambda builder, which: builder.dismiss())
            dialog.show()
        except Exception:
            self.logger.exception("shop dialog failed")

    def _shop_list(self, kind):
        state = self._pet or self._state()
        shop = SHOP_KINDS.get(kind)
        if state is None or shop is None:
            return
        species = species_of(state)
        items, ids = [], []
        for item_id, item in shop["items"].items():
            if item.get("unbuyable"):
                continue
            owned = ""
            if kind == "accessory":
                if item_id in (state.get("wardrobe") or {}).values():
                    owned = " (надето)"
                elif (state.get("inventory") or {}).get(item_id):
                    owned = " (в шкафу)"
            else:
                count = inv_count(state, item_id)
                if count:
                    owned = " (×%d)" % count
            mark = ""
            if kind == "food":
                if item_id in species.get("likes", ()):
                    mark = " ❤️"
                elif item_id in species.get("dislikes", ()):
                    mark = " 💢"
            items.append("%s %s — %s%s%s" % (
                item["emoji"], item["name"], _coins_text(item["price"]), owned, mark))
            ids.append(item_id)

        def pick(builder, index):
            try:
                builder.dismiss()
            except Exception:
                pass
            if 0 <= index < len(ids):
                self._shop_confirm(kind, ids[index])

        try:
            dialog = AlertDialogBuilder(self._activity())
            dialog.set_title(shop["title"])
            dialog.set_message("В кошельке: %s" % _coins_text(state.get("coins", 0)))
            dialog.set_items(items, pick)
            dialog.set_negative_button("Назад", lambda builder, which: self._pick_shop())
            dialog.show()
        except Exception:
            self.logger.exception("shop list failed")

    def _shop_confirm(self, kind, item_id):
        state = self._pet or self._state()
        shop = SHOP_KINDS.get(kind) or {}
        item = (shop.get("items") or {}).get(item_id)
        if state is None or item is None:
            return
        effects = item.get("effects") or {}
        effect_text = ", ".join(
            "%s%+d" % (NEED_ICONS.get(key, key), int(value))
            for key, value in effects.items()) or "эффекты скрыты до покупки"
        if kind == "toy":
            effect_text = "настроение +%d, запас %d игр" % (item["mood"], item["uses"])
        elif kind == "accessory":
            effect_text = item.get("bonus_text", "стиль и только")
        elif kind == "medicine":
            cures = ", ".join(ILLNESSES[ill]["name"].lower() for ill in item.get("cures", ()))
            effect_text = ("лечит: %s" % cures) if cures else "поддержка здоровья"

        def buy_it(builder, which):
            try:
                builder.dismiss()
            except Exception:
                pass
            ok, lines = buy(state, kind, item_id)
            self._save_state(state)
            self._after_action(ok, lines)

        try:
            dialog = AlertDialogBuilder(self._activity())
            dialog.set_title("%s %s" % (item["emoji"], item["name"]))
            dialog.set_message("%s\n%s\n%s\nЦена: %s" % (
                item.get("note", ""), random.choice(SHOP_LINES.get(kind, ("",))),
                effect_text, _coins_text(item["price"])))
            dialog.set_positive_button("Купить", buy_it)
            dialog.set_negative_button("Отмена", lambda builder, which: self._shop_list(kind))
            dialog.show()
        except Exception:
            self.logger.exception("shop confirm failed")

    # ---- кухня ----

    def _pick_recipe(self):
        state = self._pet or self._state()
        if state is None:
            return
        items, ids = [], []
        for recipe_id, recipe in RECIPES.items():
            missing = 0
            for food_id in recipe["inputs"]:
                if inv_count(state, food_id) < recipe["inputs"].count(food_id):
                    missing += 1
            mark = " ✅" if missing == 0 else (" (не хватает %d)" % missing)
            items.append("%s %s%s" % (recipe["emoji"], recipe["name"], mark))
            ids.append(recipe_id)

        def pick(builder, index):
            try:
                builder.dismiss()
            except Exception:
                pass
            if 0 <= index < len(ids):
                ok, lines = cook(state, ids[index])
                self._save_state(state)
                self._after_action(ok, lines)

        try:
            dialog = AlertDialogBuilder(self._activity())
            dialog.set_title("Кухня")
            dialog.set_message("Блюда сытнее ингредиентов по отдельности")
            dialog.set_items(items, pick)
            dialog.set_negative_button("Закрыть", lambda builder, which: builder.dismiss())
            dialog.show()
        except Exception:
            self.logger.exception("recipe dialog failed")

    # ---- кладовая и гардероб ----

    def _show_inventory(self):
        state = self._pet or self._state()
        if state is None:
            return
        inventory = state.get("inventory") or {}
        foods = [(key, entry) for key, entry in inventory.items() if entry.get("kind") == "food"]
        toys = [(key, entry) for key, entry in inventory.items() if entry.get("kind") == "toy"]
        meds = [(key, entry) for key, entry in inventory.items() if entry.get("kind") == "medicine"]
        accs = [(key, entry) for key, entry in inventory.items() if entry.get("kind") == "accessory"]

        items, actions = [], []
        if not any((foods, toys, meds, accs)):
            self._result_dialog("Кладовая", ["Пока пусто. Магазин — соседняя дверь 🛒"])
            return
        for food_id, entry in sorted(foods):
            food = food_info(food_id) or {}
            items.append("%s %s ×%d — покормить" % (food.get("emoji", "🍴"),
                                                     food.get("name", food_id), int(entry.get("count", 0))))
            actions.append(("food", food_id))
        for toy_id, entry in sorted(toys):
            toy = TOYS.get(toy_id) or {}
            items.append("%s %s (игр: %d) — поиграть" % (toy.get("emoji", "🧸"),
                                                          toy.get("name", toy_id), int(entry.get("uses", 0))))
            actions.append(("toy", toy_id))
        for med_id, entry in sorted(meds):
            med = MEDICINES.get(med_id) or {}
            items.append("%s %s ×%d — дать" % (med.get("emoji", "💊"),
                                               med.get("name", med_id), int(entry.get("count", 0))))
            actions.append(("medicine", med_id))
        for acc_id, entry in sorted(accs):
            acc = ACCESSORIES.get(acc_id) or {}
            worn = acc_id in (state.get("wardrobe") or {}).values()
            items.append("%s %s — %s" % (acc.get("emoji", "🎭"), acc.get("name", acc_id),
                                         "снять" if worn else "надеть"))
            actions.append(("accessory", acc_id))
        items.append("👨‍🍳 Готовить")
        actions.append(("cook", None))

        def pick(builder, index):
            try:
                builder.dismiss()
            except Exception:
                pass
            if not 0 <= index < len(actions):
                return
            kind, payload = actions[index]
            if kind == "cook":
                self._pick_recipe()
                return
            if kind == "food":
                ok, lines = eat_food(state, payload)
            elif kind == "toy":
                ok, lines = play_with_toy(state, payload)
            elif kind == "medicine":
                ok, lines = use_medicine(state, payload)
            elif kind == "accessory":
                slot = (ACCESSORIES.get(payload) or {}).get("slot", "head")
                if payload in (state.get("wardrobe") or {}).values():
                    ok, lines = unequip_slot(state, slot)
                else:
                    ok, lines = equip_accessory(state, payload)
            else:
                return
            self._save_state(state)
            self._after_action(ok, lines)

        try:
            dialog = AlertDialogBuilder(self._activity())
            dialog.set_title("Кладовая и гардероб")
            dialog.set_items(items, pick)
            dialog.set_negative_button("Закрыть", lambda builder, which: builder.dismiss())
            dialog.show()
        except Exception:
            self.logger.exception("inventory dialog failed")

    # ---- прогулки ----

    def _pick_location(self):
        state = self._pet or self._state()
        if state is None:
            return
        if state.get("walk"):
            self._walk_status()
            return
        items, ids = [], []
        for loc_id, loc in LOCATIONS.items():
            if loc.get("price", 0) > 0 and loc_id not in (state.get("unlocked_locations") or []):
                mark = " — открыть за %s" % _coins_text(loc["price"])
            else:
                mark = ""
            items.append("%s %s · %s%s" % (loc["emoji"], loc["name"],
                                           _minutes_text(loc["minutes"]), mark))
            ids.append(loc_id)

        def pick(builder, index):
            try:
                builder.dismiss()
            except Exception:
                pass
            if 0 <= index < len(ids):
                self._start_walk_and_show(ids[index])

        try:
            dialog = AlertDialogBuilder(self._activity())
            dialog.set_title("Куда гулять?")
            dialog.set_message("Погода будет сюрпризом. Одни места открываются за монеты")
            dialog.set_items(items, pick)
            dialog.set_negative_button("Отмена", lambda builder, which: builder.dismiss())
            dialog.show()
        except Exception:
            self.logger.exception("location dialog failed")

    def _start_walk_and_show(self, loc_id):
        state = self._pet or self._state()
        if state is None:
            return
        ok, lines = start_walk(state, loc_id)
        self._save_state(state)
        if ok:
            BulletinHelper.show_success(lines[0])
            self._walk_status()
        else:
            self._show_pet_dialog(message="\n".join(lines))

    def _walk_status(self):
        state = self._pet or self._state()
        walk = (state or {}).get("walk")
        if not walk:
            self._show_pet_dialog()
            return
        fresh, done = walk_tick(state)
        if fresh:
            self._save_state(state)
        location = LOCATIONS.get(walk.get("loc")) or {}
        weather = WEATHER.get(walk.get("weather", "sunny")) or {}
        left = max(0, walk.get("minutes", 20) - (time.time() - walk.get("started", 0)) / 60)
        lines = ["%s %s, %s %s" % (location.get("emoji", "🌳"), location.get("name", ""),
                                   weather.get("emoji", ""), weather.get("name", ""))]
        lines.append("Осталось гулять: ~%s" % _minutes_text(left))
        lines.append("Погода: %s" % weather.get("note", ""))
        log = walk.get("log") or []
        if log:
            lines.append("")
            lines.extend("• " + line for line in log[-8:])

        def home(builder, which):
            try:
                builder.dismiss()
            except Exception:
                pass
            ok, lines = finish_walk(state, early=True)
            self._save_state(state)
            self._after_action(ok, lines)

        try:
            dialog = AlertDialogBuilder(self._activity())
            dialog.set_title("На прогулке")
            dialog.set_message("\n".join(lines))
            if done:
                dialog.set_positive_button("Забрать домой", home)
            else:
                dialog.set_positive_button("Домой пораньше", home)
            dialog.set_negative_button("Пусть гуляет", lambda builder, which: builder.dismiss())
            dialog.show()
        except Exception:
            self.logger.exception("walk status failed")

    # ---- работа ----

    def _pick_job(self):
        state = self._pet or self._state()
        if state is None:
            return
        if state.get("job"):
            self._finish_job_and_show()
            return
        items, ids = [], []
        for job_id, job in JOBS.items():
            locked = int(state.get("stage", 0)) < int(job.get("min_stage", 1))
            mark = " — с %s" % STAGE_LABELS_LOWER[job["min_stage"]] if locked else ""
            items.append("%s %s · %s · %s%s" % (
                job["emoji"], job["name"], _minutes_text(job["minutes"]),
                SKILL_ICONS[job["skill"]], mark))
            ids.append(job_id)

        def pick(builder, index):
            try:
                builder.dismiss()
            except Exception:
                pass
            if 0 <= index < len(ids):
                ok, lines = start_job(state, ids[index])
                self._save_state(state)
                self._after_action(ok, lines)

        try:
            dialog = AlertDialogBuilder(self._activity())
            dialog.set_title("Кем подработать?")
            dialog.set_message("Зарплата зависит от навыка и стадии")
            dialog.set_items(items, pick)
            dialog.set_negative_button("Отмена", lambda builder, which: builder.dismiss())
            dialog.show()
        except Exception:
            self.logger.exception("job dialog failed")

    def _finish_job_and_show(self):
        state = self._pet or self._state()
        if state is None:
            return
        ok, lines = finish_job(state)
        self._save_state(state)
        self._after_action(ok, lines)

    # ---- меню «Ещё»: достижения, журнал, профиль, альбом, справка ----

    def _show_more(self):
        items = [
            "🏆 Достижения",
            "📖 Журнал жизни",
            "📊 Профиль питомца",
            "🧩 Альбом стикеров",
            "💡 Совет дня",
            "📜 Как играть",
            "🥚 Новый питомец",
        ]
        actions = (self._show_quests, self._show_journal, self._show_profile,
                   self._show_album, self._show_tip, self._show_guide, self._pick_species)

        def pick(builder, index):
            try:
                builder.dismiss()
            except Exception:
                pass
            if 0 <= index < len(actions):
                actions[index]()

        try:
            dialog = AlertDialogBuilder(self._activity())
            dialog.set_title("Ещё")
            dialog.set_items(items, pick)
            dialog.set_negative_button("Закрыть", lambda builder, which: builder.dismiss())
            dialog.show()
        except Exception:
            self.logger.exception("more dialog failed")

    def _show_quests(self):
        state = self._pet or self._state()
        if state is None:
            return
        done = state.get("quests_done") or []
        counters = state.get("counters") or {}
        lines = ["Готово: %d из %d" % (len(done), len(QUESTS)), ""]
        shown = 0
        for quest_id, quest in QUESTS.items():
            if quest_id in done:
                continue
            current = min(int(counters.get(quest["counter"], 0)), int(quest["target"]))
            lines.append("⬜ %s — %s (%d/%d)" % (
                quest["title"], quest["desc"], current, quest["target"]))
            shown += 1
            if shown >= 18:
                lines.append("…и ещё %d в списке" % (len(QUESTS) - len(done) - shown))
                break
        if not shown:
            lines.append("Все достижения собраны. Ты легенда! 🏅")
        self._result_dialog("Достижения", lines)

    def _show_journal(self):
        state = self._pet or self._state()
        if state is None:
            return
        entries = (state.get("journal") or [])[-JOURNAL_SHOW:]
        if not entries:
            self._result_dialog("Журнал", ["Жизнь только начинается — записей пока нет"])
            return
        lines = []
        for ts, kind, text in reversed(entries):
            lines.append("%s  %s" % (_clock_text(ts), text))
        self._result_dialog("Журнал жизни", lines)

    def _show_profile(self):
        state = self._pet or self._state()
        if state is None:
            return
        species = species_of(state)
        counters = state.get("counters") or {}
        skills = state.get("skills") or {}
        lines = [
            "%s %s — %s (%s)" % (_face(state), self._pet_name(state),
                                 species["stages"][int(state.get("stage", 0))], species["trait"]),
            "",
            "О виде: " + species["about"],
            "Любимое: " + ", ".join(FOODS.get(key, {}).get("name", key) for key in species.get("likes", ())),
            "Нелюбимое: " + ", ".join(FOODS.get(key, {}).get("name", key) for key in species.get("dislikes", ())),
            "",
            "Навыки:",
        ]
        for skill in SKILL_KEYS:
            xp = int(skills.get(skill, 0))
            level = skill_level(xp)
            lines.append("  %s %s — ур. %d (%d опыта)" % (SKILL_ICONS[skill], SKILL_LABELS[skill], level, xp))
        lines.extend([
            "",
            "Ранг хозяина: %s (%d очков заботы)" % (rank_of(state.get("care_score", 0)), state.get("care_score", 0)),
            "Про ранг: " + RANK_NOTES.get(rank_of(state.get("care_score", 0)), "Путь только начинается."),
            "Монет в кошельке: %s" % _coins_text(state.get("coins", 0)),
            "Заработано всего: %s" % _coins_text(counters.get("coins_earned", 0)),
            "",
            "Кормлений: %d · Игр: %d · Купаний: %d" % (
                counters.get("fed", 0), counters.get("played", 0), counters.get("washed", 0)),
            "Прогулок: %d (%d мин) · Смен: %d" % (
                counters.get("walks", 0), counters.get("walk_minutes", 0), counters.get("jobs_done", 0)),
            "Мини-игр: %d (побед: %d) · Блюд: %d" % (
                counters.get("games_played", 0), counters.get("games_won", 0), counters.get("cooked", 0)),
            "Сообщений-обедов: %d · Дней рядом: %d" % (
                counters.get("messages_fed", 0), counters.get("days_visited", 0)),
            "Болел: %d · Вылечен: %d" % (counters.get("illnesses", 0), counters.get("healed", 0)),
        ])

        def share(builder, which):
            try:
                builder.dismiss()
            except Exception:
                pass
            try:
                from android_utils import copy_to_clipboard

                copy_to_clipboard(export_state_text(state))
                BulletinHelper.show_success("Профиль скопирован — делись!")
            except Exception:
                self.logger.exception("export failed")

        try:
            dialog = AlertDialogBuilder(self._activity())
            dialog.set_title("Профиль")
            dialog.set_message("\n".join(lines))
            dialog.set_positive_button("Скопировать", share)
            dialog.set_negative_button("Закрыть", lambda builder, which: builder.dismiss())
            dialog.show()
        except Exception:
            self.logger.exception("profile dialog failed")

    def _show_album(self):
        state = self._pet or self._state()
        if state is None:
            return
        owned = state.get("collectibles") or []
        lines = ["Собрано: %d из %d" % (len(owned), len(COLLECTIBLES)), ""]
        listed = set()
        for set_name, item_ids in COLLECTIBLE_SETS.items():
            lines.append("— %s —" % set_name)
            for item_id in item_ids:
                item = COLLECTIBLES.get(item_id)
                if item is None:
                    continue
                listed.add(item_id)
                mark = item["emoji"] if item_id in owned else "❔"
                name = item["name"] if item_id in owned else "???"
                lines.append("  %s %s — %s" % (mark, name, RARITY_LABELS[item["rarity"]]))
            lines.append("")
        stray = [key for key in COLLECTIBLES if key not in listed]
        if stray:
            lines.append("— Разное —")
            for item_id in stray:
                item = COLLECTIBLES[item_id]
                mark = item["emoji"] if item_id in owned else "❔"
                name = item["name"] if item_id in owned else "???"
                lines.append("  %s %s — %s" % (mark, name, RARITY_LABELS[item["rarity"]]))
        self._result_dialog("Альбом", lines)

    def _show_tip(self):
        self._result_dialog("Совет дня", [random.choice(TIPS)])

