# ============================================================================
# СПРАВОЧНИК БАЛАНСА (для будущих правок)
# ============================================================================
# Краткая шпаргалка по всем формулам игры. Меняй константы в шапке файла —
# этот раздел объясняет, на что каждая влияет.
#
# ── ВРЕМЯ ──────────────────────────────────────────────────────────────────
# decay_rates(): каждая потребность падает на (скорость вида × базу) в час.
#   Пример: сытость дракончика — 5.0/час ⇒ с 100 до 0 за ~20 часов бодрствования.
#   Во сне действует SLEEP_RATES: всё медленнее, бодрость растёт.
#   apply_decay() докручивает часы отсутствия хозяина одним куском.
#
# ── РОСТ ───────────────────────────────────────────────────────────────────
# EVOLVE_STEPS: (минимальный возраст, минимальная забота) для перехода.
#   0→1: 20 минут и 1 прогрев (действие «согреть»).
#   1→2: 6 часов и 12 заботы (кормления/игры/купания/прогулки).
#   2→3: 72 часа и 40 заботы.
# Забота копится любым действием ухода; сбрасывается только при смене вида.
#
# ── ЭКОНОМИКА ──────────────────────────────────────────────────────────────
# Источники монет (примерно за час активной игры):
#   уход          2–6 за действие, кулдауны 10–60 минут
#   сообщения     1 монета за сообщение, капа 60/час
#   прогулка      5–20 за событие, 3–6 событий за прогулку
#   работа        14–95 за смену (25–60 минут) + уровень навыка × 3
#   мини-игры     6–19 за победу, перезарядка 3 минуты
#   дейлик        20 × серия дней (максимум 7)
#   ачивки        10–300 разово
# Стоки: еда (0–60), игрушки (22–130), аксессуары (40–110), аптека (15–75),
#   открытие локаций (90–700). Старт — 50 монет.
#
# ── БОЛЕЗНИ ────────────────────────────────────────────────────────────────
# Шансы подцепить: грязь < 20 (сыпь), голод = 0 (несварение), шторм на
# прогулке (простуда), нелюбимая еда (несварение с шансом 35%).
# Больной питомец теряет 3 здоровья/час, лечение аптечным предметом
# возвращает в строй мгновенно.
#
# ── СТИКЕРЫ ────────────────────────────────────────────────────────────────
# Редкости: обычный 46%, редкий 30%, эпический 18%, легендарный 6%.
# Дубликаты конвертируются в 8 монет, коллекция — 51 стикер.
#
# ── СКИЛЛЫ ─────────────────────────────────────────────────────────────────
# XP-пороги: 30/80/160/280/450/700/1000/1400/1900/2600 (10 уровней).
# Тренировка +14, мини-игры +4–12, прогулки +6–14, работа +10.
# Уровень 5 открывает ачивку «Мастер навыка».
#
# ── ЧАТ-КОРМ ───────────────────────────────────────────────────────────────
# Каждое отправленное сообщение: +2 сытости, +2 настроения, +1 монета,
# не больше 60 в час (CHAT_CAP_PER_HOUR). Работает в любом чате.
#
# ── СТАТУС У НИКА ──────────────────────────────────────────────────────────
# Обновляется при смене стадии/вида и раз в 6 часов (SYNC_EVERY).
# Требует премиум — это ограничение Telegram, а не плагина.

