# вливаем допреплики в базовые пулы
for _species_id, _buckets in SPECIES_MOOD_LINES_EXTRA.items():
    if _species_id not in SPECIES_MOOD_LINES:
        continue
    for _bucket, _lines in _buckets.items():
        SPECIES_MOOD_LINES[_species_id][_bucket] = (
            tuple(SPECIES_MOOD_LINES[_species_id].get(_bucket, ())) + tuple(_lines))

# ============================================================================
# ФИНАЛЬНАЯ СБОРКА
# ============================================================================
# Ниже — сводка того, что собирает этот модуль. Файл большой, поэтому
# держим ориентир по разделам (номера примерные, блоки DLC докупаются
# в конец файла и живут рядом со справочником баланса):
#
#   1. Шапка и константы баланса ................ ~100 строк
#   2. Помощники (время, множества, тексты) ..... ~350 строк
#   3. Виды, еда, рецепты, игрушки, одежда ...... ~1600 строк
#   4. Болезни, аптека, локации, погода ......... ~1200 строк
#   5. События прогулок, коллекция, работа ...... ~1500 строк
#   6. Квесты, советы, викторина, реплики ....... ~1900 строк
#   7. Движок состояния и распада ............... ~900 строк
#   8. Движок действий: еда, магазины, прогулки . ~1200 строк
#   9. Примесь TamagochiCore: хранение, статусы . ~700 строк
#  10. Примесь TamagochiDialogs: интерфейсы ...... ~1600 строк
#  11. Финальный TamagochiPlugin: настройки ...... ~600 строк
#  12. DLC-паки контента и справочник ........... остаток
#
# Инварианты, которые стоит проверять после правок:
#   • в модуле ровно один наследник BasePlugin — TamagochiPlugin;
#   • все ссылки квестов указывают на существующие предметы;
#   • «полные» цели квестов пересчитаны после DLC (см. выше);
#   • имена животных без латиницы внутри кириллических слов
#     (линтер-скрипт — tools/test_pet.py, проверка микса алфавитов).
#
# Удачной игры! 🐣

# Служебные переменные циклов вливания реплик не должны утекать в модуль.
for _cleanup_name in ("_species_id", "_extra", "_bucket", "_lines", "_buckets"):
    globals().pop(_cleanup_name, None)

# Сводка каталогов — печатается в лог при загрузке, удобно для отладки.
def _catalog_summary():
    """Короткая строка о размере контента — для журнала загрузки."""
    return (
        "виды=%d еда=%d рецепты=%d игрушки=%d аксессуары=%d "
        "локации=%d события=%d стикеры=%d работы=%d квесты=%d "
        "вопросы=%d советы=%d" % (
            len(SPECIES), len(FOODS), len(RECIPES), len(TOYS), len(ACCESSORIES),
            len(LOCATIONS), len(WALK_EVENTS), len(COLLECTIBLES), len(JOBS),
            len(QUESTS), len(QUIZ), len(TIPS),
        )
    )

# Экспорт состояния — один блок текста, чтобы поделиться питомцем.
def export_state_text(state):
    """Печатает питомца одним текстом — для друзей или бэкапа."""
    species = species_of(state)
    stage = int(state.get("stage", 0))
    needs = state.get("needs", {})
    counters = state.get("counters") or {}
    return "\\n".join([
        "🐣 Мой питомец в «Тамагочи»",
        "%s %s — %s (%s)" % (_face(state), species["label"],
                             species["stages"][stage], species["trait"]),
        "Возраст: %s · ранг: %s" % (_plural_age_line(state),
                                    rank_of(state.get("care_score", 0))),
        "Монеты: %s · стикеров: %d/%d · достижений: %d/%d" % (
            _coins_text(state.get("coins", 0)),
            len(state.get("collectibles") or []), len(COLLECTIBLES),
            len(state.get("quests_done") or []), len(QUESTS)),
        "Покормлен %d раз, погулян %d раз, вылечен %d раз" % (
            counters.get("fed", 0), counters.get("walks", 0), counters.get("healed", 0)),
    ])
